  "ex": "정답 2개(ㄴ·ㄹ).\nㄱ ✕ 외국의 정치적 주요인물은 「현재 또는 과거에」 외국에서 정치적·사회적 영향력을 가진 자와 그 가족·밀접관계자다(업무규정 제64조①). 외국정부 고위관리자의 자녀는 가족에 해당한다(제64조②1호·③1호). 「사임 후 1년 이내」라는 기간은 카지노사업자 편(제126조①)에만 있고, 금융회사 편에는 없다.\nㄴ ○ 외국의 정치적 주요인물이 신규로 계좌를 개설하는 경우 그 거래의 수용에는 고위경영진의 승인을 얻어야 한다(제66조1호).\nㄷ ✕ 이미 계좌를 개설한 고객이 외국의 정치적 주요인물로 확인된 경우에도 거래의 계속 유지에 고위경영진의 승인을 얻어야 한다(제66조2호). 결혼에 의한 친인척(사위)도 가족이다(제64조③1호).\nㄹ ○ 외국의 정치적 주요인물로 확인되면 강화된 고객확인을 하고, 계좌 거래권한을 가진 가족·밀접관계자의 성명·생년월일·국적, 관련 법인·단체 정보를 추가로 확인하는 등 재산·자금 원천 파악 조치를 해야 한다(제67조).\nㅁ ✕ 외국의 정치적 주요인물은 추가정보 확인이 필요한 고객으로서 고위험군이며 강화된 고객확인 대상이다(제30조③2호, 제55조). 위험이 높은 것으로 평가되는 경우에는 간소화된 고객확인을 적용할 수 없다(제20조②2호). 국적국의 FATF 이행 수준은 간소화 배제 사유(제20조②1호)를 피할 뿐, PEP의 고위험성을 없애지 않는다.\n함정: 카지노 편의 「사임 후 1년」을 금융회사에 끌어오기, 「기존 고객은 승인 불요」, 「FATF 이행국이면 간소화 가능」.",
