  "scene": "갑은행 기업금융팀은 2026년 10월 신규 법인고객 4곳의 거래 개시를 심사하고 있다.\n(가) 을사: 외국인 근로자·유학생이 주로 이용하는 소액해외송금업자(독립형). 여러 건의 송금신청을 모아 한 번에 해외로 보내고, 해외 협력업자에게 미리 목돈을 보내 둔 뒤 현지에서 지급하는 방식을 쓴다.\n(나) 병사: 호텔 운영사. 법인등기부에는 목적사업으로 환전업이 올라 있으나 사업자등록증에는 환전업이 없고, 환전 매출은 전체 매출의 극히 일부다.\n(다) 정사: 법인등기부 목적과 실제 영업을 보면 금전의 대부를 업으로 하고 있으나, 상호에 「대부」가 들어 있지 않고 대부업자 목록에서도 조회되지 않는다.\n(라) 무사: 직원 3명의 소규모 온라인 쇼핑몰. 연 매출에 비해 지나치게 많은 수천 개의 가상계좌 발급을 요청했다.",
