  "a": 3,
  "ex": "정답 ④.\n① ○ 소액해외송금업자의 Pooling·Pre-funding 송금은 자금세탁에 이용될 위험이 있어, 환거래 고객에 준하여 고위험 고객으로 분류하고 강화된 모니터링이 필요하다(TPAC 핵심포인트 02 업권별 위험 ‑ 소액해외송금업). 환거래 서비스 자체도 고위험 상품·서비스다(업무규정 제31조③2호).\n② ○ 가상계좌가 범죄자에게 재판매되어 대포계좌·범죄자금 이동 채널로 쓰이므로, 사업목적상 필요성·과거 사기·도박 이력·규모 대비 과도한 발급 요청을 점검하고 기 발급분을 재점검·회수하는 등 심사를 강화한다(TPAC 핵심포인트 02 은행업 ‑ 가상계좌).\n③ ○ 환전업을 주된 사업으로 하지 않는 호텔 등은 주된 수익 업종으로 위험평가하는 것이 일반적이고, 등기부에만 환전업이 있고 실제 영위·영위 예정이면 사업자등록증 정정신고를 우선 수행해야 한다(TPAC 핵심포인트 02 환전업).\n④ ✕ 대부업을 업으로 하면서 상호에 「대부」가 없거나, 상호에 있더라도 대부업자 목록에서 조회되지 않으면 오히려 고위험 고객으로 분류해 강화된 고객확인을 해야 한다(TPAC 핵심포인트 02 대부업). 대부업자는 업무규정상 추가정보 확인이 필요한 고객으로 고려해야 한다(업무규정 제30조③4호).\n⑤ ○ 대량 현금거래가 수반되는 환전영업자는 추가정보 확인이 필요한 고객으로 고려해야 하고(업무규정 제30조③4호), 고위험 고객에게는 거래목적·자금원천 등을 확인한다(제42조②③). 체크리스트·질의서 파악 후 경영진 승인을 거치는 절차는 위험관리 사례로 제시된다(TPAC 핵심포인트 02 환전업).\n함정: 「목록에 없으면 대부업자가 아니다」 — 미등록·상호 미표시 대부 영업은 위험을 낮추는 사정이 아니라 높이는 사정이다.",
