  "scene": "무궁생명은 「금융회사의 지배구조에 관한 법률」 제25조제2항에 따라 사내이사 또는 업무집행책임자 중에서 준법감시인을 두어야 하는 보험회사다. 회사 직위 체계는 전무 → 상무 → 부장 순이고, 준법감시인 Q는 전무다.\n무궁생명은 2027년 7월 보고책임자 교체를 앞두고 다음 후보를 검토하고 있다.\n- P(상무): 무궁생명 자금세탁방지부에서 자금세탁방지 업무만 전담한 경력 1년 6개월, 그 전에 리스크관리부에서 다른 업무를 주로 하면서 자금세탁방지 업무를 함께 맡은 경력 1년.\n- R(부장): 다른 보험회사 자금세탁방지부에서 자금세탁방지 업무만 전담한 경력 5년.\n- Q(전무, 준법감시인): 자금세탁방지 업무 경력 1년. 보고책임자를 겸직하는 안이 거론된다.",
