  "ex": "정답 ㄱ, ㄷ.\nㄱ ○ 보고책임자 자격요건은 금융회사등에서 2년 이상 자금세탁방지 관련 업무를 수행한 경력이며, 자금세탁방지등을 주된 업무로 하지 않은 경우에는 경력의 절반만 인정한다(업무규정 제5조②5호가목1)). 1년 6개월 + 1년×½ = 2년이므로 충족한다. 보험회사는 은행 등(제5조②5호나목1))에 속하지 않고 사내이사·업무집행책임자 중에서 준법감시인을 두어야 하는 회사이므로 직위 기준은 「준법감시인 차하위 직위 이상」이다(나목2)). 전무(준법감시인) 바로 아래인 상무는 충족한다.\nㄴ ✕ 자격요건을 갖추었더라도 직위 기준(준법감시인 차하위 직위 이상 = 상무 이상)을 충족하지 못하면 보고책임자로 임명할 수 없다(제5조②5호나목2)). 자격요건과 직위는 함께 충족해야 한다.\nㄷ ○ 준법감시인등을 보고책임자로 임명하는 경우에는 제5조②5호의 기준(자격요건·직위)을 적용하지 않는다(제5조②5호 본문 괄호).\nㄹ ✕ 준법감시인등이 보고책임자 업무를 상당한 주의로 감독할 책임은 준법감시인등이 보고책임자를 겸직하지 않는 경우에 한정된다(제5조의2②2호 괄호). 겸직하면 자기 업무를 자기가 감독하는 셈이 되므로 이 감독책임 조항은 적용되지 않는다.\n※ 자격요건 조항은 2027.5.13부터 적용된다(TPAC 핵심포인트 02, 개정 FIU규정 적용 일정). 사례의 교체 시점(2027년 7월)은 적용 이후다.\n함정: 겸무 경력 절반 인정 계산, 「자격만 갖추면 직위 무관」, 보험회사를 은행과 같은 직위 기준(사내이사·업무집행책임자)으로 착각, 겸직 시 감독책임 존속.",
