  "ex": "정답 3개(ㄴ·ㄷ·ㄹ).\nㄱ ✕ 카지노사업자가 칩과 현금·수표를 교환하는 거래(법 제2조제2호다목)는 1거래일 합산이 아니라 거래 1건당 지급·영수 금액을 기준으로 한다(시행령 제8조의2② 단서). 400만원짜리 3건은 각각 1천만원 미만이다(분할 회피가 의심되면 STR은 별개로 검토).\nㄴ ○ 카지노사업자가 지급·영수하는 권면액 100만원 초과 수표는 현금등에 들어가지만, 실지명의를 확인하고 실지명의·수표번호를 기록·관리하면 제외된다(시행령 제8조의3 단서). 남는 현금 300만원은 기준 미달이다(유권해석 사례15②).\nㄷ ○ 기록·관리하지 않았다면 권면액 500만원 수표는 현금등(시행령 제8조의3 본문)이므로, 한 건에 1,000만원+300만원=1,300만원이 되어 1천만원 이상이다.\nㄹ ○ 부동산 신탁업자가 사업비를 위탁자나 거래업체에 현금으로 지급하는 것은 금융회사등이 거래 상대방에게 현금을 지급하는 행위로 CTR 대상이다(1천만원 이상인 경우, 유권해석 사례13).\nㅁ ✕ 은행 송금서비스로 정산금을 보내는 것은 거래 상대방에게 현금등을 직접 지급한 것이 아니므로 CTR 대상이 아니다(유권해석 사례16). CTR은 현금의 물리적 이동이 있어야 한다.\n함정: 카지노의 건별 기준을 일반 금융회사의 1거래일 합산으로 착각, 「수표는 현금이 아니다」를 카지노에도 그대로 적용, 「금융회사등이 1천만원 이상 지급하면 무조건 CTR」.",
