  "ex": "정답 ㄱ, ㄴ, ㄹ.\nㄱ ○ FATF 상호평가는 40개 권고와 11개 즉시성과의 이행 현황을 약 5~6년 주기로 상호 평가(peer review)하며, 평가단은 회원국 전문가로 구성된다(TPAC 핵심포인트 03).\nㄴ ○ 2019년 제4차 평가 결과 「강화된 후속점검」 대상이었고, 2024년 10월 총회(10.21~25)에서 「정규 후속점검」으로 상향되었다. 정규 후속점검은 최고 수준 등급이다(TPAC 핵심포인트 03).\nㄷ ✕ 정규 후속점검 대상국이 3년 주기이고, 강화된 후속점검 대상국은 1회차 1.5년, 2회차부터 1년 주기로 더 자주 점검받는다. ICRG 점검 대상국은 매 FATF 총회(연 3회)마다 점검받는다(TPAC 핵심포인트 03).\nㄹ ○ 누설 금지는 FATF 권고기준 제21조 (b)항, 거짓 보고가 아닌 한 손해배상책임을 지지 않는 면책은 제21조 (a)항을 법제화한 것이다(유권해석사례집 2.0, 의심거래보고제도의 이해).\nㅁ ✕ FATF가 권고 3·38을 개정해 유죄 판결 없는 몰수, 의심거래 발생 시 거래 중지 제도 도입을 촉구한 것은 맞지만, 현행 국내 법규상 거래거절·중단은 CDD 정보를 제공하지 않은 경우에 한정되고 고객 동의 없는 일방적 계좌해지는 불가하다(TPAC 핵심포인트 08, 특금법 제5조의2④).\n함정: 「강화」라는 이름 때문에 점검 주기가 더 길다고 착각, FATF 국제기준의 촉구 사항을 국내 현행법의 권한으로 확장.",
