  "ex": "정답 ②.\n① ○ 3억원 이상 사기죄는 범죄수익은닉규제법상 중대범죄이므로, 수사기관에 신고한 경우 특금법 제4조①3호에 따라 의심거래보고 대상이다(TPAC 핵심포인트 08, STR Q&A 3).\n② ✕ 특금법과 관련 규정에는 의심거래보고 고객의 거래를 종료하는 근거 조항이 없다. 「3년 내 3회 이상 STR 고객」을 이유로 거래를 끝내는 것은 특금법에 근거한 조치가 아니다(TPAC 핵심포인트 08, 유권해석 1). 법상 거래 거절·종료 의무는 고객확인을 할 수 없는 경우 등이다(특금법 제5조의2④).\n③ ○ 3억원 미만 보험사기는 중대범죄가 아니지만, 수사 과정에서 금액이 늘거나 다른 범죄·탈세와 연결될 수 있어 수사의뢰로 신고한 사안은 STR을 적극 검토하는 것이 바람직하다(TPAC 핵심포인트 08, STR Q&A 3).\n④ ○ 보고 여부 검토자 또는 보고책임자는 내부 보고서 작성자가 될 수 없다. 예외는 소규모 금융회사등뿐이다(업무규정 제82조②). 병생명이 소규모가 아니라는 점은 문제가 준 조건이다.\n⑤ ○ 최근 3개월 거래규모 기재는 거래를 종합해 보라는 취지일 뿐, 3개월간 보고를 지체해도 된다는 뜻이 아니다. 보고대상으로 결정한 거래는 지체 없이 보고해야 한다(TPAC 핵심포인트 08, STR 작성시 참고사항 · 특금법 제4조①).\n함정: 회사 내규(반복 보고 고객 종료)를 특금법상 의무로 착각, 금액 기준 미달을 「보고 불필요」로 단정, 「3개월 종합 기재」를 보고 유예로 오해.",
