  "scene": "을은행 국제업무부는 2026년 10월 다음 네 건을 검토하고 있다. 국제업무부장은 을은행의 임원이 아니다.\n(가) X국 은행 P가 환거래계약 체결을 요청했다. 확인해 보니 P는 X국에 법인 등록만 되어 있을 뿐 영업소와 직원이 없고, 어느 나라 감독당국의 감독도 받지 않는다.\n(나) FATF 권고사항을 효과적으로 이행하는 Y국의 정상 영업 은행 Q가 환거래계약 체결을 요청했다. 계약안에는 Q의 고객이 을은행에 개설될 Q의 환거래계좌를 직접 이용해 거래할 수 있는 서비스(대리지불계좌)가 들어 있다. 국제업무부장은 이 계약을 부장 전결로 처리하려 한다.\n(다) 국내에 등록한 소액해외송금업자 R이 을은행에 계좌 개설을 신청했다. R은 관련 법령상 을은행과 같은 은행에 개설한 계좌를 통해서만 고객과 지급·수령을 할 수 있다.\n(라) 을은행과 이미 환거래계약을 맺고 있는 Z국 은행 S가 최근 위장은행에 계좌를 제공하고 있다는 정보가 들어왔다. S 자체는 Z국에서 인가받아 실제로 영업하는 은행이다.",
  "ask": "업무규정·유권해석상 을은행의 조치에 관한 설명으로 가장 옳지 않은 것은?",
