  "scene": "정생명(보험회사)은 2026.10.26(월) 고객확인 업무를 점검하면서 다음 사실을 확인했다.\n1) 정생명은 2026년 9월 K생명을 인수·합병해 K생명 계약자 3만 명이 정생명의 고객이 됐다. 정생명은 K생명으로부터 고객확인 관련 기록을 넘겨받고 고객확인 이행 보증도 받았지만, 그 자료에 대한 표본추출 점검 등 적정성 판단 절차는 거치지 않았다.\n2) 정생명은 Q은행을 통해 방카슈랑스 상품을 팔고 있다. 두 회사 사이에는 판매제휴 계약만 있고, 고객확인의무 대행에 관한 업무 위수탁 계약은 없다. Q은행은 「고객확인 최종책임은 보험사에 있다」며 정생명의 신분증 사본 제공 요청에 응하지 않고 있다.\n3) 고객 A가 계약자, A의 자녀 B가 수익자인 종신보험(타인을 위한 보험)이 체결됐다. 정생명은 수익자 지정 때에는 B의 성명 확인과 신원정보 수집 수준의 간소화된 고객확인을 하고, 보험금을 지급할 때 검증을 포함한 고객확인을 하기로 했다. 정생명의 위험평가에서 A·B와 이 계약은 자금세탁 위험이 낮은 것으로 평가됐고, 의심되는 사정도 없다.\n4) 고객 C의 배우자 D가 C의 위임장을 가지고 와서 C 명의로 저축보험 계약을 체결했다.",
  "ask": "업무규정·유권해석상 옳은 것은 모두 몇 개인가?",
