  "a": 2,
  "ex": "정답 3개(ㄷ·ㄹ·ㅁ).\nㄱ ✕ 인수·합병으로 새로 고객이 된 자도 고객확인 대상이다. 생략하려면 ① 기록 입수와 이행 보증, ② 표본추출 점검 등을 통한 적정성 판단을 「모두」 충족해야 한다(업무규정 제26조). ②가 빠졌다.\nㄴ ✕ 제3자 고객확인이 성립하려면 판매제휴 계약만이 아니라 고객확인의무 대행에 대한 업무 위수탁 계약이 있어야 하고(유권해석 사례83), 요청 시 문서사본 등을 지체 없이 제공받을 수 있어야 한다(제53조2호). 제3자가 고객확인정보의 지체 없는 제공을 거부하면 제3자 고객확인은 성립하지 않고 정생명이 직접 해야 한다(사례83).\nㄷ ○ 제3자를 통해 고객확인을 하는 경우에도 최종책임은 당해 금융회사등(위탁한 보험사)에 있다(제54조, 사례83·84).\nㄹ ○ 타인을 위한 보험에서 고객은 계약자와 수익자이고(제20조④), 수익자는 「수익자 지정 시」와 「보험금 지급 시」에 고객확인을 한다(제32조). 지급 시에는 검증을 포함한 철저한 고객확인을 하고, 지정 시에는 간소화된 고객확인을 해도 무방하다(유권해석 사례41). 간소화는 위험이 낮은 것으로 평가된 경우에만 쓸 수 있고 의심·고위험이면 쓸 수 없지만(제20조②), 이 사안은 저위험으로 평가됐다. 간소화해도 제38조의 신원확인은 생략할 수 없다.\nㅁ ○ 고객을 대신해 계좌 신규개설 등 금융거래를 하는 대리인에 대해서는 권한 확인과 함께 대리인 본인에 대한 고객확인도 해야 한다(제38조③). 보험계약 체결은 계좌의 신규 개설에 포함된다(제22조2호).\n함정: 인수·합병 생략 요건을 하나만 기억하는 ㄱ, 「판매를 맡겼으니 고객확인도 맡긴 것」이라는 ㄴ, 수익자는 지급 때만 확인한다고 보아 ㄹ을 ✕로 고르는 실수.",
