  "scene": "무진은행(시중은행) 자금세탁방지팀은 2026.11.2(월) 이사회 보고를 앞두고 내부통제 점검 결과를 정리하고 있다.\n1) A국 지점: A국의 자금세탁방지 관련 고객확인 기준은 국내 기준보다 낮다. A국 법령은 지점이 국내 기준을 적용하는 것을 막지 않는다.\n2) 교육: 보고책임자가 올해 직위·담당업무별로 나눈 자금세탁방지 교육을 화상으로 1회 실시했다. 감사팀은 「화상 교육은 교육으로 인정되지 않는다」고 지적했다.\n3) 직원알기제도: 현재 신규 채용자에 대해서만 신원사항을 확인·심사하고, 재직 중인 임직원은 대상에서 빼고 있다.\n4) 신상품: 2027년 1월 간편 해외송금 앱 서비스를 새로 출시할 예정이다.\n5) 교육 기록: 2)의 교육 일자·대상·내용을 기록해 두었다.",
