  "a": 4,
  "ex": "정답 ㄱ, ㄹ, ㅁ.\nㄱ ○ 해외지점등에 적용되는 국내법과 현지법 기준이 다르면 소재국 법령이 허용하는 범위에서 더 높은 기준을 적용하고(업무규정 제27조③), 현지 기준이 국내 기준보다 낮으면 위험을 관리·경감할 추가 조치를 취하고 금융정보분석원에 통지해야 한다(제27조④).\nㄴ ✕ 교육·연수는 집합, 전달, 화상 등 다양한 방법으로 실시할 수 있다(제9조①). 보고책임자의 연 1회 이상 실시 의무(제7조②)와 대상별 구분 실시(제8조①)도 이 사안에서 지켜졌다.\nㄷ ✕ 직원알기제도는 임·직원을 채용(재직 중 포함)하는 때에 신원사항 등을 확인·심사하는 것이다(제10조). 재직 중인 임직원을 빼는 운영은 맞지 않는다.\nㄹ ○ 신규 금융상품·서비스(새로운 기술 및 지급·결제 수단의 이용에 따른 것 포함)를 이용한 자금세탁행위등의 위험을 식별·확인·평가·이해하기 위한 정책과 절차를 수립·운영하고 위험 관리·경감 조치를 취해야 한다(제17조2호).\nㅁ ○ 교육을 실시하면 일자·대상·내용 등을 기록·보존해야 하고(제9조②), 교육내용·일자·대상자를 포함한 교육 관련 사항은 5년간 보존 대상이다(제85조④3호).\n함정: 「교육은 집합교육」이라는 오래된 관행(ㄴ), 직원알기제도의 괄호 「재직 중 포함」을 놓치는 실수(ㄷ).",
