  "scene": "갑은행(「은행법」에 따른 은행) 자금세탁방지팀은 2026.10.26(월) 가상자산 관련 법인 고객을 점검하고 있다.\n(가) 을사: 원화마켓 가상자산거래소. 2024.3.4 가상자산사업자 신고가 수리됐고, 갑은행이 실명확인입출금계정을 제공하고 있다. 담당자는 FIU 홈페이지 「가상자산사업자 신고 현황」에서 을사가 신고 수리 사업자로 게시된 것을 확인하고 고객확인을 마쳤다. 을사는 현재 정보보호 관리체계 인증 갱신을 신청했는데, 인증기관 사정으로(을사 책임 없음) 갱신 여부가 아직 결정되지 않았다.\n(나) 병사: 고객의 가상자산을 직접 받지 않고 고객 계좌에 그대로 둔 채, 거래소 API로 알고리즘 자동매매를 해 주는 프로그램을 개발·공급하고 이용료를 받는다. 신고는 하지 않았고, 갑은행에 법인 계좌 개설을 신청했다.\n(다) 정사: 가상자산과 금전의 교환이 없는 가상자산거래(코인 간 거래)만 제공하는 사업자로 신고가 수리됐고, 실명확인입출금계정이 없다. 정사는 앞으로 자기 거래소 밖에서 매도인의 청약을 관리하며 매수인을 알선해 가상자산과 원화의 매매를 중개하려 한다.",
  "ask": "옳은 것은 모두 몇 개인가?",
