  "ex": "정답 1개(ㄷ).\nㄱ ✕ 가상자산사업자인 고객은 신원 외에 신고·수리 등에 관한 사항을 확인하고, 신뢰할 수 있고 독립적인 문서·자료·정보로 검증해야 한다. 홈페이지 신고 현황만으로는 실명확인입출금계정·정보보호 관리체계 인증 여부를 확인·검증할 수 없다(특금법 제5조의2①3호, 업무규정 제37조①, 유권해석사례집 2.0 사례94).\nㄴ ✕ 특금법은 「수리한 날부터 5년 이하의 범위에서 대통령령으로 정하는 기간」으로 정하고(제7조⑥), 시행령은 이를 3년으로 정한다. 계속 영업하려면 만료 45일 전까지 갱신신고서를 내야 한다(시행령 제10조의15①②). 2024.3.4 수리분은 2027년 3월 초에 만료된다.\nㄷ ○ 정보보호 관리체계 인증 미획득은 직권말소 사유지만, 인증 갱신 신청에 대해 사업자의 책임 없는 사유로 갱신 여부가 결정되지 않은 경우는 예외다(특금법 제7조④1호 단서, 시행령 제10조의13②).\nㄹ ✕ 고객 가상자산을 직접 받지 않더라도 매도·매수 지시로 자동매매를 지원하는 프로그램을 공급하면 매도·매수의 중개·알선·대행에 포함돼 가상자산사업자에 해당할 소지가 있다(사례97). 갑은행은 가상자산사업자 해당 여부와 신고 이행 여부를 확인해야 한다(제5조의2①3호).\nㅁ ✕ 가상자산과 금전의 교환이 있는 가상자산거래를 제공하려면 실명확인입출금계정을 통해 금융거래를 해야 한다. 계정 없이 원화 매매를 중개하면 특금법 위반이다(제7조③2호, 감독규정 제27조①, 사례102).\n함정: 법률의 「5년 이하」를 유효기간 5년으로 읽는 실수(ㄴ), 「직접 보관하지 않으면 사업자가 아니다」라는 오해(ㄹ).",
