  "p": 15,
  "scene": "개인 고객 A의 2026.10.22(목) 거래다. 아래 외에 A·B는 그날 해당 금융회사들과 다른 현금거래가 없다.\n1) 09:30 을은행 창구에서 A가 을은행 본인 계좌의 현금 900만원을 인출했다.\n2) 11:00 병은행 자동화기기(공동망 CD기)에서 A가 을은행 본인 계좌의 현금 300만원을 인출했다.\n3) 13:00 A의 주택을 사들인 B가 을은행 창구에서 A 명의 주택담보대출 잔액 2,000만원을 현금으로 상환하고, 대위변제 영수증을 요청했다.\n4) 14:00 A가 병은행 창구에서 정은행이 발행한 100만원권 정액 자기앞수표 15장을 지급제시하고 현금 1,500만원을 받았다.\n5) 15:00 A가 을은행 창구에서 계좌의 1,200만원을 거래처 C 계좌로 보내면서 「현금으로 처리해 달라」고 요청했다. 실제로 현금이 오가지는 않았고, A는 현금처리가 필요한 이유를 설명하지 못했다.",
  "ask": "고액현금거래보고(CTR)에 관한 설명으로 가장 옳은 것은?",
