  "scene": "무궁증권 자금세탁방지팀은 2026.11.9(월) 경영진 보고를 앞두고 2026년 전사적 자금세탁 위험평가(EWRA) 계획서 초안을 검토하고 있다. 초안을 쓴 담당자 P는 다음 다섯 가지를 적었다.\n1) 평가 결과의 관리 방식\n2) 위험 경감 정책·통제·절차의 승인권자\n3) FIU가 실시하는 두 가지 평가(위험관리수준 평가, 종합평가)의 주기\n4) 잔여위험의 산출과 저위험 판정 시 처리\n5) 2027년 1분기 출시 예정인 비대면 해외주식 소수점 거래 서비스의 위험평가 시점",
  "ask": "P의 초안 중 옳은 것만을 모두 고른 것은?",
