  "ex": "정답 ㄱ, ㄹ.\nㄱ ○ 위험평가등의 결과를 문서화하고(업무규정 제19조①1호), 지속적으로 최신 상태로 유지하며(3호), 금융정보분석원장 및 검사수탁기관의 장에게 제공하기 위한 운영체계를 구축해야 한다(4호).\nㄴ ✕ 위험을 관리·경감하기 위해 「경영진의 승인을 거친」 정책·통제·절차를 구비해야 한다(제19조②1호).\nㄷ ✕ 주기가 뒤바뀌었다. 종합평가는 매년 실시하고(제18조), 위험관리수준 평가는 주기적으로(반기) 실시한다(제19조④, TPAC 핵심포인트 위험평가 — 위험관리수준평가 반기별 평가).\nㄹ ○ 잔여위험 = 자금세탁 위험(고유위험) − AML 내부통제(효과성). 위험이 낮아 별도 경감 조치를 취하지 않기로 한 경우에는 ML/TF 위험이 낮다는 증명이 필요하다(TPAC 핵심포인트 위험평가 — 잔여위험평가·위험경감을 위한 개선조치).\nㅁ ✕ 신규 상품·서비스(새로운 기술 이용 포함)에 내재된 위험을 식별·평가하는 절차를 갖춰야 하며(제17조2호), 신상품 등에 대한 위험평가는 고객에게 판매·제공하기 전에 실시한다(TPAC 핵심포인트 위험평가 — 상품·서비스 및 채널 위험평가, FATF R.15).\n함정: 종합평가(매년)와 위험관리수준 평가(반기)의 주기 뒤바꾸기(ㄷ), 「보고책임자 승인」과 「경영진 승인」 혼동(ㄴ).",
