  "scene": "정은행 명동지점에서 2026.10.26(월)~10.30(금) 다음 거래가 있었다. X·V·Y·Z는 정은행에 계좌가 없는 내국인이고, 아래 외에 정은행과 다른 거래가 없다.\n1) X: 10.26(월) 현금 900만원, 10.28(수) 현금 800만원, 10.30(금) 현금 400만원으로 각각 자기앞수표를 발행받았다.\n2) V: 10.27(화) 봉함된 봉투를 보호예수로 맡기면서 \"3천만원 상당의 귀금속\"이라고 말했다.\n3) Y: 10.29(목) 현금 150만원을 다른 은행에 있는 거래처 계좌로 무통장 송금했다.\n4) Z: 10.29(목) 창구에서 여권만 제시하고 예금계좌 개설을 신청했다.\n5) 내국인 W: 10.30(금) 비대면 앱에서 여권 사본을 제출했고, 정은행은 외교부 여권진위확인시스템으로 여권의 진위를 확인한 뒤 계좌를 개설해 주었다.",
  "ask": "업무규정·유권해석상 옳은 것은 모두 몇 개인가?",
