   "ㄱ. 1)의 수표 발행은 건별로는 1천만원 미만이지만 7일 동안 합산한 금액이 기준금액 이상인 연결거래이므로, 정은행은 그 뒤 X가 처음으로 금융거래를 하는 때에 X의 고객확인을 하여야 한다.",
