  "a": 1,
  "ex": "정답 2개(ㄱ·ㄴ).\nㄱ ○ 일회성 금융거래에는 동일인 명의로 7일 동안 합산한 금액이 기준금액 이상인 연결거래가 포함되고(업무규정 제23조①2호·②), 연결거래는 당해 거래당사자가 그 거래를 한 이후 최초 금융거래 시 고객확인을 한다(제23조③, 유권해석사례집 2.0 사례21). 900+800+400=2,100만원.\nㄴ ○ 보호예수는 봉함된 경우 기준금액 미만으로 본다(업무규정 제23조①3호).\nㄷ ✕ 100만원 초과 전신송금이 발생하면 송금자의 성명·주민등록번호와 수취인의 계좌번호를 확인해야 한다(업무규정 제24조③, 제46조, 시행령 제10조의8). 전신송금의 일회성 고객확인 기준금액도 100만원이다(시행령 제10조의3, TPAC 핵심포인트 CDD — 일회성 CDD 기준금액).\nㄹ ✕ 내국인이 여권만으로 거래하면 금융실명법상 실명확인은 되지만 주소를 확인할 수 없어 특정금융정보법상 신원확인은 끝나지 않는다. 주민등록초본, 성명·주소가 적힌 공공요금 청구서·영수증, 재직증명서 등 주소를 확인할 추가 서류가 필요하다(업무규정 제38조①5호, TPAC 핵심포인트 CDD — 개인 신원확인 및 검증 시 유의사항).\nㅁ ✕ 비대면 계좌개설 시 신분증 사본 제출 외에 영상통화·접근매체 전달 시 확인·기존계좌 활용·이에 준하는 방법 중 1가지가 더 이루어져야 하며, 외교부 여권진위확인만 더한 방법으로는 부족하다. 여권에 없는 주소·연락처의 확인·검증과, 비대면 거래에 따른 거래목적·자금원천 등 추가정보 확인도 필요하다(업무규정 제31조③3호·제35조·제38조①, 유권해석사례집 2.0 사례80).\n함정: 연결거래의 고객확인 시점(그 거래 이후 최초 거래, ㄱ), 금액이 작은 전신송금의 확인 의무(ㄷ), 「실명확인」과 「특금법상 신원확인」 혼동(ㄹ), 「진위확인」을 비대면 실명확인 수단으로 착각(ㅁ).",
  "src": "업무규정 제23조①②③ · 제24조③ · 제46조 · 시행령 제10조의8 · 제31조③ · 제35조 · 제38조① · 시행령 제10조의3 · 유권해석사례집 2.0 사례21·52·80 · TPAC 핵심포인트(CDD) 개인 신원확인 유의사항",
