  "scene": "갑은행 외환센터는 2026.10.27(화) 수출입 법인 고객의 무역대금 거래를 점검하다가 다음 네 곳을 골라냈다.\n(가) 을사: 사업자등록상 업종은 '중고자동차 판매'인데, 최근 3개월 동안 동남아 거래처로부터 '의류 수출대금' 명목의 외화를 7차례 받았다.\n(나) 병사: 2026년 8월 설립. 주소지는 수십 개 법인이 함께 등록된 오피스텔 한 호실이고, 직원·매장 등 영업 실체가 거의 확인되지 않는다. 설립 직후부터 '수입대금' 명목으로 해외에 5차례, 합계 미화 300만달러를 송금했다.\n(다) 정사: 화장품 수출업체. 계약서의 단가와 송장의 단가가 서로 다르고, 화물은 A국에서 출발해 B국·C국을 거쳐 D국으로 운송되었는데 경유 이유에 대한 설명이 없다.\n(라) 무사: 전자부품 수입업체. 관세청에 신고된 연간 수입금액은 30억원인데, 같은 기간 '수입대금' 명목의 해외 송금액은 120억원이다.",
  "ask": "FATF 무역기반 자금세탁(TBML) 위험지표와 국내 규정에 비추어 갑은행의 판단으로 가장 옳지 않은 것은?",
