  "a": 4,
  "ex": "정답 ⑤.\n⑤ ✕ 법인의 등록된 수출입 금액과 수출입을 위한 해외 은행 송금액이 상당히 불일치하는 것은 그 자체로 무역 서류 및 상품 위험지표다(TPAC 핵심포인트 국내제도 — FATF TBML 위험지표 2021). 명확한 경제적·법적 목적 없이 규모가 큰 거래나 비정상적인 유형의 거래는 그 배경과 목적을 최대한 검토하고 결과를 기록·관리해야 하며(업무규정 제77조), 상대국이 FATF 지정 위험국가인지와 관계없다.\n① ○ 무역 활동이 관련 법인의 명시된 비즈니스 라인과 일치하지 않는 경우(예: 자동차 딜러의 의류 수출)는 무역활동 위험지표다(같은 곳).\n② ○ 다수 등록이 가능한 주소(고밀도 주거용 건물 등)에 위치하거나 일반적인 비즈니스 활동이 현저히 부족한 것은 구조 위험지표다(같은 곳). '법인 신규 설립후 거액 해외 송금 거래'는 은행업 외환거래 STR 참고유형이다(TPAC 핵심포인트 STR — 업권별 STR 참고유형).\n③ ○ 위험이 높은 것으로 평가된 법인·단체 고객에 대해서는 회사 기본정보, 거래자금의 원천, 거래의 목적을 확인하고, 필요하다고 판단하면 예상거래 횟수·금액, 주요 공급자·주요 고객 등도 확인한다(업무규정 제42조①③).\n④ ○ 계약서·송장 등 무역 문서 간 불일치, 경제적·상업적 정당성 없이 여러 관할 구역을 통한 상품 운송은 무역 서류 및 상품 위험지표다(TPAC 핵심포인트 국내제도 — FATF TBML 위험지표 2021).\n함정: 「세관 신고를 거쳤으니 정상 거래」로 단정해 서류 금액과 자금 흐름의 불일치를 놓치는 것, 국가위험이 낮으면 거래 검토가 필요 없다고 보는 것.",
