  "scene": "을은행(임직원 3천여 명의 시중은행) 자금세탁방지팀장 P는 2026.10.28(수) 신임 직원 교육자료 초안에 최근 처리한 건과 그에 대한 설명을 다음과 같이 적었다.\n1) 10월 중 영업점에서 생성된 위험신호 120건 가운데, 점검 결과 의심스럽지 않다고 판단한 110건의 종결 처리\n2) 법인 고객 A에 대한 수사기관의 압수수색영장이 을은행에 접수되었고, 이를 처리하면서 A가 횡령 자금을 세탁하는 데 을은행 계좌를 이용했다는 정황을 알게 됨(을은행이 수사기관에 직접 신고한 건은 아님)\n3) 금융정보분석원(FIU) 소속 공무원이 을은행이 제출한 의심거래보고서에 형식적 요건의 흠결이 있다며 보정을 요구함\n4) 을은행이 속한 금융그룹의 Global Exit List(자금세탁 외에 사기·뇌물·마약 등 여러 금융범죄를 이유로 거래를 종료한 고객을 등록하는 시스템)에 거래를 종료한 법인 B를 등록하려 함\n5) 법인 고객 C의 외부 세무대리인인 T세무사가 C의 비자금 조성 정황을 알게 됨",
  "ask": "P의 설명 중 옳은 것만을 모두 고른 것은?",
