  "ex": "정답 ㄷ, ㄹ.\nㄱ ✕ 의심스럽지 않다고 판단한 위험신호는 의심스럽지 않다고 본 정확한 사유를 상세히 기술해 종결해야 하며, '일상거래'·'혐의없음'·'정상영업거래'처럼 간단히 적으면 검사에서 지적될 수 있다(TPAC 핵심포인트 STR — 영업점 점검 절차, '혐의없음' 종결 처리 보고서 작성방법, 주요 지적사항 「보고제외건에 대한 검토 불철저」).\nㄴ ✕ 금융회사에 압수수색영장이 발부되어 고객이 자금세탁행위 등에 연관된 것을 알았다면, 금융회사가 수사기관에 신고한 경우가 아니더라도 해당 거래를 STR로 보고하여야 한다(특정금융정보법 제4조①1호·2호, TPAC 핵심포인트 STR — 의심거래보고 대상 거래).\nㄷ ○ FIU 소속 공무원은 의심거래보고서의 형식적 요건에 흠결이 있으면 보정을 요구할 수 있고, 흠결이 경미하면 금융회사등에 내용을 확인해 직권으로 보정할 수 있다. 보정 또는 내용 확인을 요구받은 금융회사등은 요구한 공무원의 신분을 확인하고 그 내용을 기록·보존해야 한다(감독규정 제8조①②, TPAC 핵심포인트 STR 수록).\nㄹ ○ 공유되는 정보가 법인등기부등본상 공개정보이고 의심거래 내용·보고 여부와 이를 추정할 수 있는 정보가 공유되지 않는 한 GEL 등록은 제4조제6항 위반이 아니다. 다만 GEL 등록대상이 의심거래 보고대상으로만 이루어진 경우에는 등록 사실만으로 보고 여부가 추정될 수 있어 위반 소지가 있다(유권해석사례집 2.0 사례11).\nㅁ ✕ 의심거래보고 의무는 특정금융정보법 제2조제1호의 금융회사등에 부과되며, 변호사·세무사는 금융회사등에 포함되지 않아 FIU나 수사기관에 신고·고발할 의무가 없다(유권해석사례집 2.0 사례8).\n함정: 「수사기관 신고(제3호)가 아니면 STR 대상이 아니다」라는 축소 해석(ㄴ), 종결 사유의 형식적 기재(ㄱ), 의무 주체를 금융회사 밖으로 확장(ㅁ).",
