  "scene": "금융정보분석원(FIU)은 을은행이 2026.9.14 보고한 고객 갑(개인사업자)의 의심거래보고(STR)를 분석하고 있다. 갑은 X국에 있는 법인들로 반복해서 송금해 왔다. 분석 과정에서 다음 일이 있었다.\n1) FIU원장은 보고받은 사항이 특정금융정보법 제4조제1항의 요건에 해당한다고 판단하고, 거래자 인적사항·사용 목적·요구하는 자료의 내용을 적은 문서로 을은행장에게 갑의 외국환업무 관련 거래 자료 제공을 요구했다.\n2) FIU원장은 상호주의 원칙에 따라 X국 금융정보분석기구(외국FIU)에 갑 관련 특정금융거래정보를 제공했다. 이후 X국이 이 정보를 자국 형사재판에 쓰겠다며 동의를 요청해 왔다.\n3) 갑이 병은행 계좌에서 정은행 고객 B의 계좌로 3천만원을 국내 송금한 건에 대해, 정은행은 B의 입금 거래를 의심거래로 보고할지 검토하려고 병은행에 갑의 주민등록번호를 요청해 받았다. 정은행 직원 M은 이 번호를 사적으로 친구에게 알려 주었다.\n4) 갑은 을은행에 「내 동의 없이 거래정보를 FIU에 넘긴 것은 금융실명법상 비밀보장 위반」이라고 항의했다.",
