  "ex": "정답 2개(ㄱ·ㄹ).\nㄱ ○ FIU원장은 보고받은 사항이 제4조제1항의 요건에 해당한다고 판단하는 경우에만, 거래자의 인적사항·사용 목적·요구하는 정보 또는 자료의 내용을 적은 문서로 금융회사등의 장에게 외국환업무에 따른 거래 관련 정보·자료를 요구할 수 있고, 이 요구는 필요한 최소한으로만 하여야 한다(특정금융정보법 제13조③④).\nㄴ ✕ 외국의 요청을 받아 제공한 정보를 그 나라 형사사건의 수사나 재판에 쓰는 것에 동의하려면 법무부장관의 동의를 받아야 한다(제11조③).\nㄷ ✕ 외국FIU에 제공하려면 ①목적 외 용도 사용 금지 ②제공 사실의 비밀 유지 ③FIU원장의 사전 동의 없이 외국의 형사사건 수사나 재판에 쓰지 않을 것 — 세 요건을 모두 충족해야 한다(제11조②).\nㄹ ○ 수취 금융회사에 종사하는 사람은 제5조의3에 따라 제공받은 정보를 다른 사람에게 제공·누설하거나 목적 외로 사용해서는 안 되고(제12조①3호의2), 이를 위반하면 5년 이하의 징역 또는 5천만원 이하의 벌금에 처한다(제16조2호). 국내송금에서 수취 금융회사가 STR 보고를 위해 송금 금융회사에 주민등록번호를 요청하는 것 자체는 적법하다(제5조의3②1호).\nㅁ ✕ 제4조(의심거래보고)·제4조의2(고액현금거래보고) 등은 금융실명법 제4조에 우선하여 적용한다(제14조①).\n함정: 동의 주체를 FIU원장으로 좁히는 ㄴ, 세 요건 중 '외국 형사절차 사전 동의'를 빠뜨린 ㄷ, '실명법 비밀보장이 항상 우선'이라는 ㅁ.",
