  "scene": "정은행 거래모니터링팀은 2026년 10월 다음 두 고객을 검토했다.\n1) 고객 Q(상품권 매매업, 개인사업자)는 9~10월 매 영업일 3천만~5천만원의 현금을 자기 계좌에 입금하고, 다음 영업일에 같은 금액을 현금으로 인출해 달라고 요청해 왔다. Q는 「상품권은 현금으로 사고팔기 때문에 매출 범위 안의 정상 거래」라고 설명했다. 보고책임자는 10.29(목) Q의 거래를 의심되는 거래 보고대상으로 결정했다.\n2) 고객 R(해외 본사를 둔 귀금속 판매업체의 국내 법인)은 연말 특별시즌에 매일 수억원의 현금을 입금한다. R은 「본사 AML 정책에 따라 현금 구매 고객 명단을 따로 확인하고 있다」고 설명했다. R은 특정금융정보법상 금융회사등에 해당하지 않는다.",
