  "a": 3,
  "ex": "정답 ④.\n① ○ 보고책임자가 의심되는 거래 보고대상으로 결정한 날부터 3영업일 이내에 보고하여야 한다(감독규정 제3조). 10.30(금)·11.2(월)·11.3(화)이 3영업일이므로 11.2 보고는 기한 안이다.\n② ○ 상품권 매매업체에는 CDD 재이행을 위해 매출 증빙·부가세 납부 증빙 제출을 요청하고, 증빙하지 못하면 현금거래 중단 등 조치를 할 수 있다(TPAC 핵심포인트 STR Q&A 7). 고객이 정보 제공을 거부하는 등 고객확인을 할 수 없으면 거래를 종료해야 하고, 이때 의심거래보고 여부를 검토해야 한다(특정금융정보법 제5조의2④1호·⑤).\n③ ○ CTR(제4조의2)과 STR(제4조)은 별개의 의무다. 상품권 매매업체의 거액 현금거래는 조세탈루·뇌물 위험으로 STR 보고 대상이 될 수 있다(TPAC 핵심포인트 STR Q&A 7).\n④ ✕ CTR 보고 제외는 다른 금융회사등, 국가·지방자치단체·공공단체와의 거래, 일상적 거래로 법령이 정한 것에 한한다(제4조의2①1~3호). R은 금융회사등이 아니므로 자체 AML 정책이 있어도 제외 대상이 아니다.\n⑤ ○ 카지노사업자 외 DNFBPs에는 의무가 없고, 귀금속상은 현금 출처 확인 통제가 충분하지 않으므로 거액 현금거래는 STR로 보고하는 것이 바람직하다(TPAC 핵심포인트 STR Q&A 8). 금융회사등이 수수한 재산이 불법재산이라고 의심되는 합당한 근거가 있으면 보고 의무가 생긴다(제4조①1호).\n함정: 「상대방이 자체 AML을 하니 CTR 제외」 — CTR 제외 대상(다른 금융회사등)을 '통제가 갖춰진 고객'으로 넓히는 것. 「상대방에 의무가 없으니 STR도 없다」는 반대 방향 착각도 함께 묻는다.",
