  "ex": "정답 ㄱ, ㄷ, ㅁ.\nㄱ ○ 금융정보분석원장 또는 그 위탁을 받아 감독·검사를 하는 자는 감독·검사에 필요한 경우 금융회사등의 장에게 금융거래등 정보나 제4조·제4조의2에 따라 보고한 정보를 요구할 수 있고, 이 요구는 필요한 최소한에 그쳐야 한다(특정금융정보법 제15조⑥⑦).\nㄴ ✕ 금융정보분석원장은 퇴임한 임원·퇴직한 직원이 재임·재직 중이었다면 제15조제3항의 조치를 받았을 것으로 인정되면 그 조치 내용을 해당 금융회사등의 장에게 통보할 수 있다(제15조의3①, 2026.8.20 시행). 금융감독원장 등에 위탁해 통보하게 할 수도 있다(같은 조③).\nㄷ ○ 통보를 받은 금융회사등의 장은 이를 퇴임·퇴직한 임직원에게 통보하고 그 내용을 기록·유지하여야 한다(제15조의3②).\nㄹ ✕ 원본·사본·마이크로필름·스캔·전산화 등 다양한 형태로 내부관리 절차에 따라 보존할 수 있고(업무규정 제86조②), 보존 장소도 본점 또는 문서보관소다(제87조).\nㅁ ○ 보고책임자의 책임하에 보안이 유지되도록 보존자료를 관리하고, 금융정보분석원장 또는 검사업무를 위탁받은 기관의 장이 자료를 요구하면 적시에 제공하여야 한다(업무규정 제86조③④).\n함정: 「퇴임하면 제재 효과도 끝난다」(ㄴ), 「보존은 원본·본점만」(ㄹ) — 신설 조문(퇴임 임원 조치 통보)과 보존 방법의 유연성을 동시에 묻는다.",
