  "scene": "무궁은행 고객 A(내국인 개인)의 2026.10.27(화) 거래 내역이다. A는 그날 무궁은행에서 아래 외에 다른 현금거래가 없다.\n1) 09:30 창구 — A가 원화 현금 600만원을 가져와, 달러로 환산해 본인 외화예금계좌에 입금\n2) 10:10 창구 — A 본인 외화예금계좌에서 미화 현금 5천달러(약 700만원 상당)를 외화 그대로 인출\n3) 11:00 창구 — A 본인 원화계좌에 현금 300만원 입금. 13:00에 A의 요청으로 이 입금거래를 같은 날 취소하고 현금 300만원을 돌려줌\n4) 15:00 창구 — A가 본인 대출의 이자 120만원과 중도상환수수료 30만원을 현금으로 납부\n5) 16:40 영업 마감 후 — A가 본인 원화계좌에 현금 250만원 입금(계리일자는 다음 영업일인 10.28)",
  "ask": "고액현금거래보고(CTR)에 관한 설명으로 옳은 것은 모두 몇 개인가?",
