  "ex": "정답 3개(ㄱ·ㄹ·ㅁ).\nㄱ ○ 원화 현금을 받아 외화로 환산해 외화예금계좌에 넣는 거래는 계좌거래에 따른 원화 현금 영수이므로 CTR 합산 대상이다(TPAC 핵심포인트 07, CTR Q&A 14).\nㄴ ✕ CTR 대상 현금에서 외국통화는 제외된다(특금법 제4조의2①). 외화예금계좌에서 외화 현금으로 인출하는 것은 외화 현금거래라 보고 대상이 아니다. 원화로 환전해 인출해야 합산 대상이 된다(CTR Q&A 15).\nㄷ ✕ 입·출금 후 당일자로 취소된 거래는 금융거래가 발생하지 않은 것으로 보아 보고 대상에서 뺀다. 정정·환입·환출, 당일 이외의 취소는 보고 대상이다(CTR Q&A 21).\nㄹ ○ 대출이자·보증료처럼 금융거래 성격의 이자는 합산하고, 중도상환수수료·중도해지수수료·증명서 발급수수료 같은 순수 수수료는 합산에서 뺀다(CTR Q&A 12).\nㅁ ○ 마감후거래는 계리일자와 관계없이 거래가 발생한 당일(10.27)을 합산 기준일로 한다(CTR Q&A 20). 지급과 영수는 따로 합산하므로(시행령 제8조의2②, CTR Q&A 3) 영수는 600+120+250=970만원 < 1천만원, 지급은 원화 현금 0원이다. 보고 대상이 아니다.\n함정: 취소분 300만원을 넣으면 1,270만원, 수수료 30만원만 넣어도 정확히 1,000만원(「이상」이므로 보고 대상)이 된다. 외화 인출을 원화로 환산해 지급에 넣는 것도 흔한 오답이다.",
