  "scene": "X국은 FATF가 성명서(Public Statement)로 발표하는 고위험 국가(Higher-risk countries) 리스트에 올라 있고, FATF 권고사항을 효과적으로 이행하는 국가가 아니다. 갑은행 외환센터는 2026.10.28(수) X국과 관련된 다음 건을 검토하고 있다.\n(가) X국 국적의 개인 B(국내 체류)가 예금계좌 신규 개설을 신청했다. 갑은행 자체 고객위험평가 모형은 B의 직업·예상 거래규모만으로 「저위험」을 산출했다.\n(나) 대한민국 국적의 E는 X국에 거주하며, 갑은행에 해외송금 거래를 신청했다.\n(다) X국 소재 은행 Z(X국 감독당국의 감독을 받음)는 B가 Z에 계좌를 열 때 이미 고객확인을 했다며, 그 정보를 갑은행의 고객확인에 갈음해 활용하라고 제안했다.\n(라) X국 소재 법인 D사(갑은행 외화계좌 보유)는 최근 명목이 불분명한 거액 입출금을 반복하고 있고, 갑은행은 그 거래의 명확한 경제적·법적 목적을 확인하지 못했다.\n(마) 금융정보분석원장은 X국의 위험에 상응하여, X국에 소재하는 고객에 대한 대리지불계좌 개설을 금지하도록 갑은행에 요청했다.",
  "ask": "업무규정상 갑은행의 조치로 가장 옳은 것은?",
