  "a": 0,
  "ex": "정답 ①.\n① ○ FATF 지정 위험국가의 고객과 금융거래를 하면서 명확한 경제적·법적 목적을 확인할 수 없으면 그 거래의 배경과 목적을 최대한 조사하여야 하고, 금융정보분석원장이 요청하면 결과를 제공하여야 한다(업무규정 제71조①②). X국은 FATF 성명서상 고위험 국가이므로 FATF 지정 위험국가다(제69조1호).\n② ✕ 외국인 고객이 FATF 권고사항을 효과적으로 이행하는 국가의 국민이 아니면 간소화된 고객확인을 적용할 수 없다(제20조②1호). 또 FATF 지정 위험국가의 고객에게는 강화된 고객확인을 하여야 한다(제72조①1호).\n③ ✕ 요주의 인물 확인 대상에는 FATF 지정 위험국가의 「국적자 또는 거주자」가 포함된다(제43조①3호). X국 거주자인 E도 대상이다.\n④ ✕ 제3자가 국외에 거주하는 자이면 FATF 권고사항을 도입해 효과적으로 이행하는 국가에 거주하는 자에 한하여 제3자 고객확인을 할 수 있다(제53조4호). 또 제3자를 통한 고객확인의 최종책임은 당해 금융회사(갑은행)에 있다(제54조).\n⑤ ✕ 금융정보분석원장은 관련 국가의 위험에 상응하여 대리지불계좌 개설 금지 등 대응조치(FATF 국제기준에 따른 대응조치 포함)를 요청할 수 있고, 이 경우 금융회사등은 그 요청에 따라야 한다(제72조②3호).\n함정: 자체 모형의 「저위험」이 국가 요건을 이긴다고 착각(②), 「국적자」만 보고 「거주자」를 빠뜨림(③), 제3자 고객확인의 책임 주체 혼동(④), FIU 요청을 권고로 오해(⑤).",
  "src": "업무규정 제20조②1호 · 제43조①3호 · 제53조4호 · 제54조 · 제69조 · 제71조①② · 제72조①②3호",
