  "scene": "금융정보분석원(FIU) 기획행정실 사무관 J는 2026년 10월 두 가지 업무를 맡았다.\n첫째, A국 금융감독·검사기관이 A국 법령(자금세탁 방지 관련 국제기구 권고사항을 반영한 법령) 위반 혐의와 관련해, 목적과 범위를 밝혀 국내 금융회사 을은행의 A국 고객 관련 업무를 특정금융정보법이 정하는 방법으로 감독·검사해 달라고 요청해 왔다. FIU원장으로부터 검사를 위탁받은 금융감독원이 실무를 맡을 예정이다.\n둘째, 2026년 정기국회에 보고할 FIU 업무 현황 자료를 준비하고 있다.\nJ가 정리한 검토 메모는 다음과 같다.",
  "ask": "J의 메모 중 옳은 것만을 모두 고른 것은?",
