  "ex": "정답 ㄱ, ㄷ, ㅁ.\nㄱ ○ 협조 주체인 「금융정보분석원장」에는 제15조제6항에 따라 권한을 위탁받은 자가 포함된다. 외국 금융감독·검사기관이 외국법령 위반행위에 대해 목적·범위 등을 밝혀 이 법의 방법에 따른 감독·검사를 요청하면 협조할 수 있고, 상호주의 원칙에 따라 감독·검사자료를 제공하거나 제공받을 수 있다(특금법 제15조의2①).\nㄴ ✕ 자료 및 제공사실의 비밀 유지가 제공 요건이지만, 감독·검사자료가 제공된 목적 범위에서 외국법령에 따른 처분 또는 그에 상응하는 절차에 사용되는 경우는 예외다(제15조의2②2호 단서). 목적 외 용도 사용 금지(같은 항 1호)와 함께 두 요건을 모두 충족해야 제공할 수 있다.\nㄷ ○ FIU원장은 매년 정기국회에 제4조에 따라 금융회사등으로부터 보고받은 건수, 특정금융거래정보 제공 요구·제공 건수, 제10조의2에 따른 통보 및 통보유예 현황 통계자료, 외국금융정보분석기구와 정보를 교환한 건수 등을 보고하여야 한다(제3조④).\nㄹ ✕ FIU는 사무를 독립적으로 수행하며, 그 소속 공무원은 이 법과 테러자금금지법에 따른 업무 외에 다른 업무에 종사하지 못한다(제3조②). 원장 승인으로 겸할 수 있다는 예외는 없다.\nㅁ ○ 외국 기관 요청에 따른 감독·검사에도 제15조제7항이 준용되므로(제15조의2③), 감독·검사에 필요하면 금융회사등의 장에게 금융거래등의 정보나 제4조·제4조의2에 따라 보고한 정보를 요구할 수 있고, 그 요구는 필요한 최소한에 그쳐야 한다(제15조⑦).\n함정: 비밀유지 요건의 단서(외국법령상 처분 사용 허용)를 놓침(ㄴ), 「독립성」을 겸직 허용으로 오해(ㄹ), 외국 요청 검사에는 정보 요구권이 없다고 착각(ㅁ).",
