  "scene": "무궁은행 강남지점에서 2026.10.26(월)~10.30(금)에 있었던 일이다.\n1) 10.26 丁이 甲·乙·丙 세 사람의 위임장과 세 사람의 실명확인증표를 가지고 와서, 세 사람 명의의 요구불예금 계좌를 한꺼번에 개설해 달라고 했다. 丁은 세 사람과 친인척 관계가 아니고, 개설 사유는 「지인들 부탁」이라고만 했다.\n2) 10.27 기존 고객 A(2025년 고객확인 완료, 재이행 주기 미도래, 기존 확인사항에 의심되는 점 없음)를 대신해, 그동안 A의 거래를 대리해 온 B(고객확인 완료)가 아니라 처음 보는 C가 A의 위임장을 가지고 와서 A 명의 정기예금 계좌를 새로 개설했다.\n3) 10.28 E가 D 명의 통장과 D의 위임장을 가지고 와서 D 계좌에서 현금 1,500만원을 출금한 뒤, 그 자리에서 그 현금으로 E 자신 명의의 무통장송금을 해 F에게 1,500만원을 보냈다.\n4) 10.29 X국 법인 G사가 외화예금계좌 개설을 신청했다. G사는 X국 개인정보 보호법을 이유로 대표자의 생년월일과 국적을 알려 주지 않았다. 지점은 대표자 정보를 받으려고 최선을 다했다는 경위를 문서로 남기고 계좌를 개설했다.\n5) 10.30 개인 고객 H(일반 위험 등급, 무궁은행 내규상 재이행 주기 3년)는 2024.3 고객확인 후 1년 7개월 동안 거래가 없다가 이날 거래를 다시 시작했다.",
