  "ex": "정답 2개(ㄴ·ㄷ).\nㄱ ✕ 대리인 丁과 본인 甲·乙·丙 각각의 고객확인, 丁의 위임 권한 확인에 더해, 동일 대리인이 여러 명의 신규계좌를 개설하는 것은 자금세탁 위험이 높을 수 있으므로 합리적 사유가 있는지 확인하고, 의심되는 합당한 근거가 있으면 의심거래보고를 고려해야 한다(업무규정 제38조③, 유권해석 사례44).\nㄴ ○ 이미 고객확인을 한 고객과 다시 거래할 때는 고객확인을 생략할 수 있다(시행령 제10조의6③, 사례35). 그러나 기존 대리인이 아닌 새 대리인이 거래하면 「기존 확인사항이 사실과 일치하지 아니할 우려가 있는 경우」에 해당하므로, 본인 확인은 생략하더라도 새 대리인에 대해서는 고객확인을 해야 한다(사례48).\nㄷ ○ 계좌에 의한 현금출금은 고객확인 대상이 아니다. 이어진 송금에서는 송금의뢰인 E가 고객확인 대상이다(사례43①). 1,500만원 무통장송금은 기준금액(1천만원) 이상의 일회성 금융거래다(업무규정 제23조①1호).\nㄹ ✕ 시행령 제10조의4는 국내·해외 법인 공통으로 대표자의 성명·생년월일·국적 확인을 규정하므로, 최선의 노력을 문서화했다는 것만으로 고객확인 의무를 이행했다고 볼 수 없다(사례32). 고객확인을 할 수 없으면 신규 거래를 거절하고 의심거래보고 여부를 검토해야 한다(특금법 제5조의2④⑤).\nㅁ ✕ 1년 이상 거래가 없었더라도 거래 재개 시점만으로 재이행 주기를 정하는 것이 아니라, 고객의 거래행위 등을 고려한 위험도에 따라 금융회사가 자체 설정·운용하는 재이행 주기에 따른다(업무규정 제34조③, 사례37).\n함정: 「서류가 다 갖춰졌으면 끝」(ㄱ), 「기존 고객이면 대리인도 생략」(ㄴ을 ✕로), 「최선을 다했다는 기록 = 이행」(ㄹ), 「휴면 후 재개 = 주기 재기산」(ㅁ).",
