  "scene": "정은행 PB센터는 2026년 10월 고객 Q(개인사업자, 금융자산 약 300억원)에게 투자자문·세무설계·상속설계를 묶은 종합자산관리서비스를 제공하기로 했다. 정은행은 자체 기준에 따라 Q를 「추가정보 확인이 필요한 종합자산관리서비스 고객」으로 선정했고, Q를 자금세탁 위험이 특히 높은 고객으로 판단하고 있다. PB센터는 Q의 금융거래를 승인·처리하는 부서다.\n1) Q는 10.26(월) 정은행에 투자자문 연계계좌를 새로 개설해 달라고 신청했다.\n2) Q는 개인자산을 신탁받아 보유할 목적으로 설립한 가족법인 R(대표이사 Q, Q 지분 100%)의 계좌 개설도 함께 신청했다.\n3) Q의 기존 예금계좌는 평균 잔액이 5억원 안팎인데, 최근 3개월 입출금 합계가 400억원을 넘었다.\n4) PB센터장은 「VIP 고객은 전담 PB가 가장 잘 안다」며 Q의 거래 모니터링을 PB센터가 직접 맡는다는 방침을 세웠다.",
