  "a": 4,
  "ex": "정답 ⑤.\n⑤ ○ 추가정보 확인이 필요한 종합자산관리서비스 고객에게는 강화된 고객확인을 해야 하고(업무규정 제62조①), 그런 고객으로 선정되었거나 신규로 편입된 고객이 계좌를 신규로 개설할 때에는 강화된 고객확인으로 얻은 신원정보 등의 적정성과 거래의 수용 여부에 대해 관리자의 검토·승인을 얻어야 한다(제62조②).\n① ✕ 금융회사등은 「자체 기준」을 마련하여 추가정보 확인이 필요한 고객을 선정하여야 한다(제61조②). 업무규정에 자산 규모 기준은 없다.\n② ✕ 개인자산을 신탁받아 보유할 목적으로 설립·운영되는 법인 또는 단체는 추가정보 확인이 필요한 고객으로 「고려하여야」 하는 고위험군이다(제30조③8호, 제55조①). 실제소유자가 분명한지와는 별개다.\n③ ✕ 잔액 규모에 비해 예금회전수가 지나치게 큰 경우는 특별한 주의를 기울여야 하는 비정상적 거래이고, 그 배경과 목적을 최대한 검토하고 결과를 기록·관리하여야 한다(제77조①2호·②·③).\n④ ✕ 자금세탁 위험이 특히 높다고 판단되는 추가정보 확인 필요 고객은 업무상 또는 조직체계상 금융거래 승인부서와 「독립된」 부서에서 지속적으로 모니터링하도록 해야 한다(제63조②). PB센터는 Q의 거래를 승인·처리하는 부서다. 고객과의 밀착·비밀보장 문화·수익 중심 보상이 고액자산가 채널의 대표적 자금세탁 취약점이다(TPAC 핵심포인트 06).\n함정: 「잘 아는 부서가 감시」(④), 「소유구조가 단순하면 저위험」(②), 「부자는 돈이 많이 도는 게 정상」(③), 「선정 기준은 당국이 정한다」(①).",
