  "scene": "정은행 영업점에서 2026년 10월 다음 일이 있었다.\n1) 직원 S는 고객 P(갑사 경리부장)의 계좌로 최근 6개월간 들어온 8억원이 P가 갑사 자금을 빼돌린 업무상횡령의 범죄수익이라는 사실을 알게 되었다. P는 횡령에 앞서 실제로는 없는 컨설팅 용역계약서를 미리 꾸며 두고, 그 계약을 근거로 회사 돈을 자기 계좌로 옮겼다. P는 아직 횡령죄로 기소되거나 처벌받지 않았다.\n2) P는 압류에 대비해 그 돈 중 3억원을 친구 Q의 실명으로 개설한 예금에 넣었다. 창구 직원 S2는 강제집행을 피하려는 P의 목적을 알면서 Q 명의 예금 개설을 주선했다.\n3) S의 보고를 받은 자금세탁방지팀 L은 사내 교육용 메모를 다음과 같이 작성했다.",
  "ask": "범죄수익은닉규제법과 금융실명법에 관한 L의 메모 중 옳은 것만을 모두 고른 것은?",
