  "ex": "정답 ㄱ, ㄹ, ㅂ.\nㄱ ○ 금융회사등 종사자는 금융거래등과 관련하여 수수한 재산이 범죄수익등이라는 사실을 알게 되었을 때 다른 법률의 규정에도 불구하고 지체 없이 관할 수사기관에 신고하여야 하고(범죄수익은닉규제법 제5조①), 이를 위반하면 2년 이하의 징역 또는 1천만원 이하의 벌금에 처한다(같은 조 ③). 신고한 경우 금융회사등은 FIU에도 지체 없이 보고해야 한다(특금법 제4조①3호).\nㄴ ✕ 자금세탁범죄는 전제범죄와 별개로 처벌된다. 전제가 되는 본 범죄가 먼저 처벌되어야만 자금세탁범죄로 처벌되는 것은 아니다(TPAC 핵심포인트 08 「자금세탁행위」, 05 「전제범죄와 별도로 자금세탁행위 자체를 범죄로 처벌」). 업무상횡령은 장기 3년 이상 징역에 해당하는 중대범죄로 전제범죄가 된다(범죄수익은닉규제법 제2조1호가목).\nㄷ ✕ 「범죄수익의 발생 원인에 관한 사실을 가장」하는 행위(제3조①2호)는 존재하지 않는 사실을 존재하는 것처럼 가장하는 행위 등으로서, 시간적으로 범죄수익을 발생시키는 범죄행위의 기수 이전의 행위라도 해당할 수 있다(대법원 2019.8.29. 선고 2018도2738 전원합의체 판결, 2014도11042 판결).\nㄹ ○ 제3조①의 미수범은 처벌하고(제3조②), 제3조①의 죄를 범할 목적으로 예비하거나 음모한 자는 2년 이하의 징역 또는 1천만원 이하의 벌금에 처한다(제3조③).\nㅁ ✕ 몰수할 재산을 몰수할 수 없으면 그 가액을 추징할 수 있지만(제10조①), 그 재산이 범죄피해재산인 경우에는 가액을 추징할 수 없다(제10조②).\nㅂ ○ 누구든지 강제집행의 면탈 등 탈법행위를 목적으로 타인의 실명으로 금융거래를 하여서는 아니 되고(금융실명법 제3조③), 금융회사등 종사자는 그 거래를 알선하거나 중개하여서는 아니 된다(제3조④). 실명이 확인된 계좌에 보유한 금융자산은 명의자의 소유로 추정한다(제3조⑤).\n함정: 「전제범죄 처벌이 먼저」(ㄴ), 「범죄 전의 가장은 가장이 아니다」(ㄷ), 몰수 불가 → 무조건 추징(ㅁ). 추징 예외(범죄피해재산)와 차명계좌 소유 추정(출연자가 아니라 명의자)은 시험에 자주 나오는 숫자 아닌 함정이다.",
