  "scene": "무은행 고객 B(개인)의 2026.10.20(화) 거래 내역이다. B는 아래 외에 이날 무은행과 다른 거래가 없다.\n1) 09:20 B는 무은행이 발행한 무기명 양도성예금증서(CD)를 지급제시하고 만기상환금 700만원을 현금으로 받았다. 이 CD는 2026년 4월 C가 자기 실명을 확인받고 발행을 의뢰한 것을 B가 넘겨받은 것이다.\n2) 10:10 B는 통장을 이용해 본인 계좌에 현금 90만원을 입금했다.\n3) 11:00 B는 거래처 E에게 150만원을 무통장 송금하면서 현금 50만원과 자기앞수표 100만원을 냈다.\n4) 14:00 B는 본인 계좌에서 현금 350만원을 인출했다.\n5) 15:30 B는 자신이 수익자로 지정된 타익신탁(위탁자 F)의 이자 40만원을 창구에서 현금으로 받았다.",
  "ask": "고액현금거래보고(CTR)에 관한 다음 설명 중 옳은 것은 모두 몇 개인가?",
