  "ex": "정답 3개(ㄷ·ㄹ·ㅁ).\nㄱ ✕ 무기명 CD는 발행 시에는 발행의뢰인 명의로 합산하지만, 만기상환 시에는 최종 소지인(해지의뢰인) 명의로 합산한다(TPAC 핵심포인트 07 CTR Q&A 6). 1)의 700만원은 B 명의 지급이다.\nㄴ ✕ 합산에서 빼는 것은 100만원 이하의 원화송금(무통장입금 포함) 금액이다. 통장·카드·모바일 칩 등을 이용한 100만원 이하 입금은 계좌에 의한 거래로서 합산 대상이다(TPAC 핵심포인트 07 CTR Q&A 18, 시행령 제8조의2④1호).\nㄷ ○ 송금 금액이 100만원을 넘으면 합산 제외 대상이 아니고, CTR은 현금의 물리적 이동만 보므로 현금 부분 50만원만 합산한다(TPAC 핵심포인트 07 CTR Q&A 17, 무통장 송금 시 유의사항).\nㄹ ○ 타익신탁 이자를 고객 계좌로 직접 이체해 지급하면 대체거래로 CTR 대상이 아니고, 고객이 현금으로 받으면 수익자 명의로 합산한다(TPAC 핵심포인트 07 CTR Q&A 7, Q&A 1).\nㅁ ○ 지급 금액과 영수 금액은 따로 합산한다(특금법 제4조의2①, 시행령 제8조의2②). B 명의 지급 현금 = 700(1) + 350(4) + 40(5, 수익자 B 명의) = 1,090만원 ≥ 1천만원. 영수 현금은 90 + 50 = 140만원.\n함정: CD는 「발행할 때 실명확인한 사람」이 아니라 「돈을 받아 가는 최종 소지인」(ㄱ), 100만원 이하 제외는 「송금」에만 적용(ㄴ). ㄱ을 맞게 보면 B의 지급은 390만원이 되어 ㅁ까지 함께 틀린다.",
