  "scene": "무은행 자금세탁방지부는 2026년 10월 고액현금거래보고(CTR) 업무를 자체 점검하다가 다음 사실을 발견했다.\n1) A지점 직원은 「공공기관의 운영에 관한 법률」에 따른 공공기관으로 알리오에 공시된 갑공단의 현금 입금 1,500만원을 「공공단체와의 거래」라며 CTR 보고대상에서 제외했다.\n2) B지점 직원은 지로장표를 쓰지 않고 시행사인 을건설이 발행한 납부고지서로 아파트 중도금 2,000만원을 현금으로 수납하면서, 공과금 수납과 같다며 합산에서 제외했다.\n3) 9월 차세대 시스템 전환 과정의 전송 오류로 CTR 대상 거래 40건이 거래일부터 45일이 지난 뒤에야 보고되었다.\n4) C지점 창구직원이 고객의 계좌이체(대체거래)를 현금거래로 잘못 기표해, 실제 현금 이동이 없는 거래가 이미 CTR로 보고되어 있었다.\n5) CTR 보고면제 대상 고객은 고객 명칭에 「은행」·「증권」이 들어가면 시스템이 자동으로 등록하고, 등록 시 증빙 첨부나 보고책임자 승인 절차는 없다.",
  "ask": "무은행의 처리 또는 판단으로 가장 옳은 것은?",
