   "4)의 오보고는 신속히 취소해야 하며, 취소를 요청할 때에는 기보고한 문서번호를 기재하고 「금융회사 등 직원의 오조작으로 인한 취소 등」의 사유를 기재한다.",
   "1)의 갑공단은 「공공기관의 운영에 관한 법률」에 따른 공공기관이므로 CTR 보고 면제 대상이어서, A지점의 처리는 정당하다.",
   "2)의 중도금은 납부고지서에 의해 수납한 금액이므로 공과금 등 수납 금액으로 보아 합산에서 제외한 B지점의 처리는 정당하다.",
   "3)은 보고가 늦었을 뿐 결국 보고되었으므로, 미보고와 달리 과태료 부과 대상이 되지 않는다.",
   "5)의 방식이라도 다른 금융회사등과의 현금거래는 법상 보고 제외 대상이므로, 명칭으로 판단해 등록하고 보고책임자 승인 없이 운영해도 문제가 없다."
