  "a": 0,
  "ex": "정답 ①.\n① ○ 금융회사가 CTR 오류를 발견하면 내부보고체계를 거쳐 해당 오보고를 신속하게 취소하고, 취소 또는 정정 요청 시 기보고한 문서번호를 기재하고 CTR 보고양식에 「금융회사 등 직원의 오조작으로 인한 취소 등」 사유를 기재한다(TPAC 핵심포인트 07 「오보고 등에 대한 취소절차」). 현금 이동이 없는 거래의 오보고는 FIU 정보제공 후 명의인 통보(특금법 제10조의2①)로 불필요한 민원을 부를 수 있다.\n② ✕ 공공기관은 과거 CTR 보고면제 대상이었으나 2019년 7월 시행령 개정으로 면제 대상 고객에서 제외되어 현재는 보고대상이다(TPAC 핵심포인트 07 「CTR보고 면제 대상」, CTR Q&A 25).\n③ ✕ 금융실명법상 공과금과 은행지로장표에 의하지 않은 「기타 각종 납부고지서」에 의한 수납은 합산대상이다. 지로장표를 쓰지 않은 건설회사 납부고지서에 의한 아파트 중도금 수납이 대표 예다(TPAC 핵심포인트 07 CTR Q&A 26).\n④ ✕ CTR 미보고·지연보고는 3천만원 이하 과태료 대상이며, 지연보고도 미보고에 해당한다(특금법 제4조의2①·제20조②1호, TPAC 핵심포인트 07 「CTR 미보고·지연보고」). 기한은 거래일부터 30일이다.\n⑤ ✕ 보고예외 대상을 고객 이름만으로 추정하거나 사업자번호 체계로 제외하면 누락·오보고 위험이 있으므로, 검증 문서를 증빙으로 첨부해 보고책임자 승인을 받고 면제 대상을 별도 관리하며 정기적으로 검증해야 한다(TPAC 핵심포인트 07 「주의사항」). 다른 금융회사등이라도 카지노사업자·가상자산사업자 등은 면제에서 빠진다(특금법 제4조의2①1호, TPAC 핵심포인트 07 「CTR보고 면제 대상」).\n함정: 「공공기관 = 면제」(②, 2019년 이후 아님), 「납부고지서 = 공과금」(③), 「지연은 미보고가 아니다」(④).",
