  "scene": "기은행(임직원 1,500명)은 준법감시인을 둘 법령상 의무가 있고, 준법감시인과 보고책임자는 서로 다른 사람이다. 기은행은 2026년 11월 자금세탁방지 체계 개편안을 마련하면서 다음 쟁점을 검토했다.\n1) 9월 거래모니터링에서 추출된 법인 R의 거래를 담당자 U가 분석한 결과 의심되는 거래가 아니라고 판단해 FIU에 보고하지 않기로 했다. U가 R의 자금 원천을 조사한 메모와 자료가 남아 있다.\n2) 특정금융정보법 제5조제1항제2호에 따른 절차 및 업무지침(업무지침)을 전면 개정하려 한다.\n3) 영업점 직원 V는 고객 S의 거래가 마약 판매대금 세탁으로 의심된다. S는 평소 「은행이 왜 자꾸 캐묻느냐」고 따져 왔고, V는 자금 원천을 묻는 고객확인 절차를 진행하면 S가 자신이 의심받고 있다는 사실을 눈치챌 우려가 있다고 합리적으로 판단했다.\n4) 임직원이 직무를 수행할 때 업무지침을 지키는지 감독하는 역할을 누구에게 맡길지 정하려 한다.\n5) 거래모니터링에서 식별된 비정상적 거래의 분석 절차를 정비하려 한다.",
  "ask": "기은행의 검토 의견 중 옳은 것만을 모두 고른 것은?",
