  "ex": "정답 ㄴ, ㄷ, ㅁ.\nㄱ ✕ 의심되는 거래 미보고 대상에 대하여 자금세탁행위등의 가능성과 관련하여 조사하였던 기록 및 기타 자료도 보존 대상이며(업무규정 제85조③3호), 금융거래관계가 종료된 때부터 5년 이상 보존해야 한다(제84조①). 분석자료도 5년 이상 보존한다(제80조).\nㄴ ○ 업무지침에는 위험을 식별·분석·평가하여 위험도에 따라 관리수준을 차등화하는 업무체계(특금법 제5조③1호)와, 방지 업무 수행 부서로부터 독립된 부서나 기관에서 적절성·효과성을 검토·평가하고 문제점을 개선하는 업무체계(같은 항 2호)가 포함되어야 한다.\nㄷ ○ 고객의 자금세탁행위등이 의심되나 고객확인 절차를 수행하는 것이 비밀 누설의 우려가 있다고 합리적으로 판단되면 고객확인 절차를 중단하고 법 제4조에 따른 의심되는 거래보고 의무를 이행하여야 한다(업무규정 제44조의2).\nㄹ ✕ 임직원의 업무지침 준수 여부 감독(특금법 제5조④)은 준법감시인등에게 부여하는 역할이다(업무규정 제5조의2①②1호). 보고책임자에게 부여하는 것은 준법감시인등을 둘 법령상 의무가 없는 금융회사등의 경우다(제5조의2① 단서).\nㅁ ○ 비정상적 거래 분석 절차에는 분석 담당 직원 지정, 과거 금융거래·신용정보 등을 활용한 분석, 고객 최신 정보 갱신, 의심되는 거래로 판단 시 FIU 보고, 분석 완료 후 분석내용의 정보화가 포함되어야 한다(업무규정 제79조).\n함정: 「보고 안 한 건은 기록도 필요 없다」(ㄱ), 「업무지침 준수 감독 = 보고책임자」(ㄹ). 준법감시인을 둘 의무가 있는지가 ㄹ의 갈림길이다.",
