  "scene": "갑은행 여의도지점은 2026.11.2(월)~11.4(수) 다음 법인·단체 고객의 계좌 개설 신청을 받았다. 괄호 안은 갑은행 자체 위험평가 결과다.\n1) A사(비상장 영리법인): 상호가 「□□유통조합」이다. 담당 직원은 「이름에 조합이 들어가니 공공단체 아니냐」며 실제소유자 확인을 생략하려 했다. (중위험)\n2) B신탁: 위탁자 P가 자기 소유 상가를 맡긴 부동산관리신탁이다. 수탁자 C신탁회사가 임대료 수납용 신탁계좌 개설을 신청했고, 수익자는 P의 자녀 Q다. (중위험)\n3) D사: 코스닥 상장법인으로 「자본시장과 금융투자업에 관한 법률」 제159조제1항에 따른 사업보고서 제출대상 법인이다. 급여이체용 계좌를 신청했다. (저위험)\n4) E사: X국에 본점을 둔 외국법인으로, 국내 지사 운영비 계좌를 신청했다. 대표자는 X국 국적의 R이다. (중위험)\n5) F사: 설립 2개월, 직원 3명인 비상장 영리법인으로, 법인 명의 보통예금 계좌를 신청했다. (중위험)",
  "ask": "갑은행의 고객확인에 관한 설명으로 옳은 것은 모두 몇 개인가?",
