  "ex": "정답 4개(ㄱ·ㄷ·ㄹ·ㅁ).\nㄱ ○ 법인명에 「××조합」·「○○유한공사」 같은 명칭이 들어 있다는 것만으로 공공단체로 판단해 실제소유자 확인을 생략해서는 안 된다(TPAC 핵심포인트 06 「실제 소유자 확인 면제 대상 여부 확인 시 유의사항」). 확인을 하지 않을 수 있는 법인·단체는 국가·지자체, 법령에 열거된 공공단체, 다른 금융회사등, 사업보고서 제출대상 법인 등으로 한정된다(시행령 제10조의5⑤).\nㄴ ✕ 신탁과 금융거래를 하는 경우 고객은 위탁자·수탁자·신탁관리인·수익자를 포함하고, 수탁자는 수탁인으로서의 지위를 금융회사등에 공개해야 한다(업무규정 제20조⑤). 신탁의 경우 위탁자·수탁자·신탁관리인·수익자의 신원정보를 확인한다(제38조②7호).\nㄷ ○ 상장기업이라고 고객확인의무 적용을 배제하기는 어렵고, 명의자인 상장기업이 맞는지 확인·검증해야 한다. 다만 사업보고서 제출대상 법인은 실제소유자 확인의무를 면제할 수 있다(유권해석사례집 2.0 사례57, 시행령 제10조의5⑤4호).\nㄹ ○ 외국법인은 본점 및 사업장 소재지로 연락 가능한 실제 사업장 소재지를 확인하고 검증한다(업무규정 제38조②3호·제40조①3호). 대표자 정보는 개인고객의 신원확인 사항에 준하며(제38조②4호), 법인 고객은 대표자의 성명·생년월일·국적을 확인한다(시행령 제10조의4 2호·4호).\nㅁ ○ 법인·단체 고객은 법인등기부등본 등 설립사실을 증명할 수 있는 문서로 법인이 실제로 존재하는지 확인하고(업무규정 제38조④), 영위하는 사업의 성격·지배구조·통제구조를 이해해야 한다(제37조③).\n함정: 「계좌 명의인 = 고객 전부」(ㄴ, 신탁은 위탁자·수익자까지 고객). 「상장사 = 고객확인 면제」로 외운 사람은 ㄷ을 틀리게 본다 — 고객확인은 하고, 면제할 수 있는 것은 실제소유자 확인뿐이다.",
