  "ex": "정답 ㄱ, ㄹ.\nㄱ ○ 국가위험을 평가할 때는 FATF 성명서 등의 고위험 국가 리스트, UN 또는 타 국제기구의 제재·봉쇄 관련 국가리스트, 국제투명성기구 등의 부패 관련 국가리스트 같은 공신력 있는 기관의 자료를 활용해야 한다(업무규정 제29조②1·3·5호).\nㄴ ✕ 위험평가는 해당 고객의 위험도가 적정하게 반영되도록 해야 한다(제28조③). 고객위험평가를 인당 기준이 아니라 ID 기준으로 운영한 것은 위험평가 모형이 합리적으로 설계되지 않았다고 지적된 제재사례다(TPAC 핵심포인트 06 「위험평가모델 제재사례」).\nㄷ ✕ 기존고객의 신규거래는 신규위험 평가모델과 행동위험 평가모델을 순차 적용해 하나라도 고위험이면 고위험 고객으로 식별해야 한다. 신규모델로만 평가해 행동모델상 고위험 고객이 중·저위험으로 바뀐 것은 부실 운영 제재사례다(TPAC 핵심포인트 06 「위험평가모델 제재사례」).\nㄹ ○ 사기이용계좌 등록 정보를 고객확인 시 참고할 수 있게 시스템을 개선하고 등록 이력을 고객위험평가에 반영하도록 개선을 요구한 사례에 부합한다(TPAC 핵심포인트 06 「필수 고위험 고객군 – 내부통제」).\nㅁ ✕ 금융회사는 위험평가 결과를 지속적으로 최신 상태로 유지해야 하고(제19조①3호), 위험평가모형이 위험을 충실히 반영하는지 정기적으로 점검하는 체계를 두지 않은 것은 제재사례다(TPAC 핵심포인트 06 「위험평가모델 제재사례」). FIU의 위험관리수준 평가(제19조④)는 FIU가 금융회사의 조치가 위험에 상응하는지 평가하는 것으로, 금융회사의 자체 점검을 대신하지 않는다.\n함정: 「FIU가 평가하니 자체 검증은 필요 없다」(ㅁ), 「신규모델로 다시 돌리면 최신 평가다」(ㄷ).",
