  "scene": "병은행 종로지점에 2026.11.3(화) 비영리 사단법인 「희망다리」가 후원금 계좌 개설을 신청했다. 희망다리는 2025년에 설립되었고, 정관상 목적은 해외 분쟁지역 난민 구호다.\n대표자 G는 「거리 모금과 후원 행사에서 모은 현금을 매주 입금하고, 매달 분쟁지역 인접국의 협력단체 두 곳으로 해외송금하겠다」고 말했다.\nG는 협력단체의 명칭만 제시했을 뿐, 실제 수혜자 명단이나 자금 집행 계획서는 아직 없다고 했다. 병은행은 희망다리를 자금세탁·테러자금조달 위험이 높은 고객으로 평가했다.",
