  "ex": "정답 ①.\n① ✕ FATF는 각국이 위험기반접근법에 맞춰 합법적인 NPO 활동을 과도하게 방해하거나 억제하지 않으면서 집중적·비례적인 위험기반 조치를 취하도록 한다(TPAC 핵심포인트 05 「비영리단체(NPO) 제도 이해」). 금융회사는 위험을 평가해 고객확인에 활용하고(업무규정 제28조①), 별도로 규정되지 않은 고위험군에도 강화된 고객확인 등 필요한 조치를 취한다(제55조②·제56조). 거래 거절·종료 의무는 고객확인을 할 수 없는 경우 등에 생긴다(특금법 제5조의2④).\n② ○ 비영리단체는 영리법인에 비해 설립이 간편하고, 설립목적의 공공성 등으로 상대적으로 완화된 감독기준이 적용되며, 기부금 등 대부분의 기금이 현금 형태다(TPAC 핵심포인트 06 「강화된 고객확인제도 (4) 비영리단체」).\n③ ○ 비영리법인 고객의 신원 확인사항은 실지명의·설립목적·주된 사무소의 소재지·연락처·대표자의 성명·생년월일·국적이다(시행령 제10조의4 3호). 설립목적은 검증 대상 정보이기도 하다(업무규정 제38조②6호·제40조①5호).\n④ ○ 위험이 높은 것으로 평가된 법인·단체 고객은 거래자금의 원천·거래의 목적 등 추가정보를 확인해야 한다(업무규정 제42조①③). 비영리단체의 확인·검증 예시로 설립목적, 조직체계, 기부 관련 정보, 주요 기부자·수혜자 정보, 모금·운영·집행자금 정보가 제시된다(TPAC 핵심포인트 06 「(4) 비영리단체」).\n⑤ ○ 국세청, 비영리민간단체 공익활동 지원사업 관리정보시스템 등에서 국내 비영리단체의 설립목적을 포함한 상세 정보를 확인·검증한다(TPAC 핵심포인트 06 「(4) 비영리단체」·「법인고객 신원확인정보 검증방법」).\n함정: 「위험이 높다 = 거래 거절 의무」. 고위험은 강화된 고객확인 대상이지 일률 거절 사유가 아니다. 비영리단체는 업무규정 제30조③의 필수 고위험 고객 목록에 없지만, 자체 평가로 고위험이면 제56조로 같은 조치를 한다.",
