  "ex": "정답 ㄱ, ㄷ, ㅁ.\nㄱ ○ 금융회사등은 금융거래가 완료되기 전에 요주의 인물 리스트(1호: 공중협박자금조달금지법에서 금융위원회가 고시하는 금융거래제한대상자 리스트, 2호: UN 지정 제재대상자 등)와 비교해, 거래고객(대리인, 실제소유자, 법인·단체 고객의 대표자 포함)이 요주의 인물인지 확인하는 절차를 수립·운영해야 한다(업무규정 제43조①).\nㄴ ✕ 지정·고시 주체는 금융위원회이고 근거는 공중협박자금조달금지법 제4조①이다(TPAC 핵심포인트 05 「테러자금금지법」).\nㄷ ○ 금융회사등(종사자 포함)은 금융위원회 허가(같은 법 제4조④)를 받은 경우가 아니면 금융거래등제한대상자의 금융거래등 및 그에 따른 지급·영수 업무를 취급해서는 안 되고(제5조①), 이를 위반해 업무를 취급한 종사자는 3년 이하의 징역 또는 3천만원 이하의 벌금에 처한다(제6조②5호).\nㄹ ✕ 금융회사등의 종사자는 수수한 재산이 공중협박자금이라는 사실을 알게 되면 다른 법률에도 불구하고 지체 없이 관할 수사기관에 신고하여야 한다(같은 법 제5조②). 신고하지 않으면 2년 이하의 징역 또는 1천만원 이하의 벌금 대상이다(제6조③1호).\nㅁ ○ 공중협박자금조달금지법 제5조②에 따라 종사자가 관할 수사기관에 신고한 경우, 금융회사등은 지체 없이 FIU원장에게 보고하여야 한다(특금법 제4조①3호). 수사기관 신고와 FIU 보고는 별개 의무다.\nㅂ ✕ 신고 사실은 거래상대방을 포함한 다른 사람에게 누설하면 안 되지만, 동일한 금융회사등의 내부에서 대량살상무기확산등을 방지하기 위해 필요한 경우 그 신고사실을 제공하는 것은 예외다(같은 법 제5조③ 단서).\n함정: 「STR 했으니 수사기관 신고는 생략」·「지정 주체는 FIU」. 테러자금은 수사기관 신고(테러자금금지법)와 FIU 보고(특금법 제4조①3호)를 둘 다 해야 하고, 지정·허가는 금융위원회가 한다.",
