  "a": 2,
  "ex": "정답 3개(ㄱ·ㄹ·ㅂ).\nㄱ ○ 금융거래등의 상대방이 금액을 분할하여 거래한다고 의심되는 경우, 금융거래등의 상대방 수, 거래횟수, 거래 점포 수, 거래 기간 등을 고려하여 의심되는 거래 보고대상인지 판단한다(감독규정 제4조①, 특금법 제4조의2②).\nㄴ ✕ 의심되는 거래를 보고한 후에도 그 보고와 관련된 상대방이 의심되는 거래 보고대상 금융거래등을 하고 있다고 의심되면 이를 FIU원장에게 보고하여야 한다(감독규정 제4조②).\nㄷ ✕ CTR 합산은 동일인(실지명의) 기준이지만(TPAC 핵심포인트 07 「동일인」), STR의 분할거래 판단은 별개다. 다수 가족 명의 계좌로 CTR 기준금액 미만 거래를 하는 것은 분할거래 STR의 대표 예시이고(TPAC 핵심포인트 08 「고액현금거래 기준 금액을 회피하기 위하여 분할거래를 하는 경우」), 다수인이 상대방이 되어 금액을 나누는 것도 분할거래 예시다(같은 자료 「분할거래의 예시」).\nㄹ ○ 동일고객의 동일유형 거래가 반복되면 일정기간 거래를 종합해 보고하는 것이 바람직하지만, 기존과 다른 의심거래 유형이 발생하면 STR 보고가 이루어지도록 해야 한다(TPAC 핵심포인트 08 STR Q&A 4). 의심되는 거래는 지체 없이 보고함이 원칙이다(특금법 제4조①, 같은 자료 「STR 작성시 참고사항」 거래내역 2).\nㅁ ✕ 금액 표기 단위는 (백만원) 단위로 통일하여 기재한다(TPAC 핵심포인트 08 「STR 작성시 참고사항」 거래내역 1).\nㅂ ○ 정형화파일에 계좌번호를 표기해 첨부한 경우 종합의견란에는 계좌번호 기재를 지양하고, 다수 계좌 사용 등 기재가 필요한 경우 계좌 끝번호(****계좌) 정도만 간략히 기재한다(같은 자료 거래내역 7).\n함정: 「CTR 합산 단위(동일인) = STR 분할거래 판단 단위」로 착각, 「한 번 보고한 고객은 끝」으로 착각. STR은 명의를 넘어 거래 패턴 전체로 판단하고, 보고 후에도 계속 보고한다.",
