  "p": 15,
  "scene": "을은행 자금세탁방지팀은 2026.11.9(월) 경영진 보고를 앞두고, FATF 권고기준 제16조(전신송금)의 국내 이행 현황을 점검하고 있다. 점검 대상은 다음과 같다.\n1) 체크카드로 카드 가맹점에서 상품을 구입하면서 그 대금을 지불하기 위해 일어나는 이체\n2) 을은행이 중개 금융회사로 참여한 국외 송금 가운데, 기술적 제약으로 전자적 방식의 정보 제공이 어려운 건\n3) 을은행이 수취 금융회사로 받은 해외송금 가운데 송금인 정보가 빠진 USD 8,000 송금 1건\n4) 을은행과 제휴한 영국 본사의 해외송금네트워크 회사가 「우리 회사도 송금정보를 받는 수취 금융회사에 해당하느냐」고 물어 온 건\n아울러 이 보고에는 같은 FATF 기준이 가상자산 이전에 적용된 자금이동규칙(트래블룰)도 참고로 넣기로 했다.",
  "ask": "점검 결과에 대한 설명으로 가장 옳지 않은 것은?",
