  "ch": [
   "가상자산사업자가 다른 가상자산사업자에게 100만원 상당 이상의 가상자산을 이전할 때에는 보내는 고객과 받는 고객의 성명, 가상자산 주소를 이전과 함께 제공해야 하고, FIU원장이나 이전받는 사업자가 요청하면 요청받은 날부터 3영업일 이내에 보내는 고객의 주민등록번호 등을 제공해야 한다.",
   "1)처럼 카드 가맹점에서 체크카드로 상품·서비스 대금을 지불하기 위한 이체에는 전신송금 정보의 확인·보관 규정을 적용하지 않을 수 있다.",
   "2)에서 을은행은 수취 금융회사가 요청하면 3일 이내에 다른 방법으로 전신송금정보를 제공해야 한다.",
   "3)처럼 송금인 정보가 누락된 전신송금을 받은 수취 금융회사는 위험 수준과 관계없이 그 거래를 거절해야 하며, 송금 금융회사에 정보를 요청하는 방식으로 처리해서는 안 된다.",
   "4)의 수취 금융회사는 특정금융정보법상 금융회사등에 한정되지 않고, 한국 또는 외국 법령에 따라 설립되어 외국 간 지급·수령의 외국환업무를 업으로 하는 자로 해석할 수 있다."
  ],
  "a": 3,
  "ex": "정답 ④.\n① ○ 트래블룰은 가상자산사업자가 다른 가상자산사업자에게 100만원 상당 이상의 가상자산을 이전하는 경우에 적용되고, 보내는 고객과 받는 고객의 성명·가상자산 주소를 이전과 함께 제공한다. FIU원장 또는 이전받는 사업자가 요청하면 요청받은 날부터 3영업일 이내에 보내는 고객의 주민등록번호 등을 제공해야 한다(TPAC 핵심포인트 05 「가상자산사업자를 위한 자금이동규칙」).\n② ○ 100만원(외화는 1천 미합중국달러) 초과 국내·외 전신송금에는 고객 관련 정보를 확인·보관하지만, 카드 가맹점에서 신용·직불·체크카드 등으로 상품·서비스 대금을 지불하기 위한 이체에는 적용하지 않을 수 있다(업무규정 제46조 단서 2호).\n③ ○ 중개 금융회사등은 전신송금정보를 수취 금융회사등에 제공해야 하고, 기술적 제약으로 전자적 방식 제공이 어려우면 수취 금융회사등의 요청이 있는 경우 3일 이내에 다른 방법으로 제공해야 한다(업무규정 제48조①).\n④ ✕ 중개·수취 금융회사등은 정보 누락 여부를 확인하는 모니터링 등 합리적 조치를 취하고(업무규정 제48조②), 정보가 누락된 전신송금에 대해 송금 금융회사등에 정보 제공을 요청할지 거래를 거절할지 등 적절한 후속조치를 결정하기 위한 위험기반 정책 및 절차를 수립·운영해야 한다(같은 조 ③). FATF 권고기준 제16조도 정보가 결여된 전신송금을 탐지·감시하고 적절한 조치를 취하도록 할 뿐, 일률 거절을 요구하지 않는다.\n⑤ ○ FATF 권고기준은 수취 금융회사 대상을 구체적으로 제한하지 않고, 입법 취지인 UN 안보리 결의 등에 따른 금융거래제한의 수범대상자도 특정금융정보법상 금융회사에 한정되지 않는다. 따라서 수취 금융회사는 한국 또는 외국 법령에 따라 설립되고 외국 간 지급 및 수령의 외국환업무를 업으로 하는 자로 해석할 수 있다(유권해석사례집 2.0 사례88).\n함정: 「정보 누락 = 무조건 거절」. 전신송금 정보 누락은 위험기반으로 후속조치(정보 요청·거절 등)를 정하는 사안이다. 같은 「3일」이라도 중개 금융회사의 대체 제공(업무규정 제48조①)과 송금 금융회사의 국내송금 정보 제공(특금법 제5조의3③, 3영업일)은 근거가 다르다.",
