  "scene": "경은행(신용카드업 겸영) 고액현금거래보고(CTR) 담당자 M은 2026.11.4(수) 거래분 중 전산이 걸러 낸 아래 건을 점검하고 있다.\n1) 외국인 고객 F는 오전 본점에서 여권으로 실명확인한 계좌(전산상 실명조합번호 부여)에 현금 600만원을, 오후 다른 지점에서 외국인등록증으로 개설한 계좌에 현금 500만원을 입금했다. 전산상 두 실명번호는 서로 연결되어 있지 않다. 오후 창구직원은 F가 「번호가 다르면 따로 계산되느냐」고 여러 번 물었다고 메모했다.\n2) 고객 G와 배우자 H의 공동명의 예금(전산에 등록된 주된 고객은 G)에 H가 창구에서 현금 1,200만원을 입금했다. G와 H는 그날 다른 현금거래가 없다.\n3) 고객 J는 본인 신용카드로 현금서비스 600만원을, J 본인 명의 한도에 통합되어 운용되는 배우자 명의 가족카드로 현금서비스 500만원을 창구에서 각각 현금으로 받았다.\n4) 고객 L은 창구에서 경은행이 판매를 대행하는 상품권 1,500만원어치를 현금으로 샀다.\n5) 마감 후 시재 점검에서 출납과잉금 200만원이 생겼다.\nM은 점검 메모를 아래와 같이 정리했다.",
