  "ex": "정답 3개(ㄱ·ㄷ·ㅁ).\nㄱ ○ 동일 외국인이 여권·외국인등록증 등 서로 다른 실명확인증표로 거래하면 전산상 동일인 파악이 어려워, 특별한 사정이 없는 한 실명번호별로 개별 합산해 보고대상 여부를 정한다. 다만 외국인이 자금세탁 목적으로 의도적으로 서로 다른 실명확인증표를 이용한다는 의심이 있으면 의심거래보고 여부를 검토해야 한다(TPAC 핵심포인트 07 CTR Q&A 5, 특금법 제4조①).\nㄴ ✕ 공동명의 예금은 신규 때 전산에 등록된 주된 고객 명의(G)로 합산한다(같은 자료 Q&A 10). 동일인 판단은 실지명의 기준이다(같은 자료 「동일인」).\nㄷ ○ 가족명의 신용카드 한도는 본인 명의로 통합 운용되므로 가족명의 카드의 현금서비스 사용액은 본인(J) 명의로 합산한다(같은 자료 Q&A 4). 600+500=1,100만원 ≥ 1천만원이므로 보고 대상이다(특금법 제4조의2①).\nㄹ ✕ 금융회사가 판매를 대행하는 상품권·복권·공연입장권 등의 판매는 특정금융정보법 제2조제2호의 금융거래에 해당하지 않으므로 합산에서 제외한다(같은 자료 Q&A 22, 「예외 사항」④).\nㅁ ○ 출납과잉금은 금융회사와 거래자 사이의 현금의 물리적 이동이 아니므로 합산 제외이고, 추후 정당거래를 파악하여 고객과 사이에 현금의 물리적 이동이 일어나면 합산한다(같은 자료 Q&A 19).\n함정: 「현금을 들고 온 사람 = 보고대상자」(공동명의는 주된 고객 명의), 「은행 창구의 현금 영수 = 모두 CTR」(상품권 판매는 금융거래가 아님). CTR은 누구의 실지명의로, 무엇이 금융거래인지 두 단계로 따진다.",
