  "scene": "신증권(투자매매·투자중개업자) 자금세탁방지팀은 2026.11.6(금), 보존기간이 지난 자료를 정리하는 계획을 세우면서 다음 건을 검토했다.\n※ 금융거래등 정보의 보존의무(현행 특정금융정보법 제5조의4)는 2019.7.1 시행되었다.\n1) 고객 A는 신증권 위탁계좌로 파생상품시장에서 선물거래를 하다가 2020.3.20 마지막 포지션을 청산해 거래종료일이 도래했다. A의 위탁계좌는 해지하지 않아 지금도 개설되어 있다.\n2) 신증권은 2015.5.11 고객 B의 거래를 의심거래로 보고했고, 그 보고 관련 자료(실지명의 확인자료·보고대상 거래자료·의심되는 합당한 근거를 기록한 자료)를 지금까지 보관하고 있다. B와의 모든 채권채무관계는 2022.6.30 끝났다.\n3) 신증권은 2014.1.20 고객 C의 거래를 의심거래로 보고했고, 그 보고 관련 자료를 보고일부터 5년이 지난 2019.3월에 폐기했다.\n4) 일부 지점은 의심거래 보고서와 그 관련 자료를 고객별 일반 거래서류철에 다른 금융거래 자료와 섞어 보관하고 있다.\n5) 2023.9월 실시한 자금세탁방지 직원 교육의 일자·대상자·내용 기록이 남아 있다.\n팀은 검토 의견을 아래와 같이 적었다.",
