  "ex": "정답 ㄷ, ㄹ.\nㄱ ✕ 파생상품시장 거래의 「금융거래등의 관계가 종료한 때」는 거래종료일이 도래한 날이지만, 고객의 계좌가 개설되어 있는 경우에는 그 계좌가 폐쇄된 날로 본다(특금법 제5조의4②2호). A의 위탁계좌가 아직 열려 있으므로 5년 보존기간은 시작되지도 않았다.\nㄴ ✕ 2019.7.1 기준으로 구법에 따른 보고일부터 5년(2020.5.11)이 지나지 않아 보관하고 있던 의심거래 보고 관련 정보는 신법에 따라 금융거래관계가 종료한 때부터 5년간 보존해야 한다(유권해석사례집 2.0 사례91 ➋). B는 2022.6.30 관계가 끝났으므로 2027.6.30까지 보존해야 한다(특금법 제5조의4①1호·②1호).\nㄷ ○ 2019.7.1 기준으로 구법에 따른 의심거래 보고일부터 5년이 지나 관련 자료를 더 이상 보관하지 않는 경우에는 구법이 적용된다(사례91 ➊, 행정기본법 제14조①). 구법은 보고 관련 자료를 보고한 날부터 5년간 보존하도록 했다.\nㄹ ○ 금융회사등은 법 제4조제1항에 따른 보고를 한 때에는 해당 보고서와 법 제5조의4제1항제1호 각 목의 자료를 다른 금융거래등에 관한 자료와 구분하여 보존해야 한다(특금법 시행령 제10조의9①).\nㅁ ✕ 자금세탁방지등에 관한 교육내용·일자·대상자를 포함한 교육 관련 사항은 5년간 보존해야 하는 자료다(업무규정 제85조④3호, 제9조②). 2023.9월 교육 기록은 아직 5년이 지나지 않았다.\n함정: 「거래가 끝난 날 = 기산점」(계좌가 살아 있으면 계좌 폐쇄일), 「구법 기간이 지났으니 폐기」(2019.7.1에 보관 중이던 자료는 신법 기준으로 다시 계산). 기산점과 경과 규정을 함께 따져야 한다.",
