  "a": 4,
  "ex": "정답 ⑤.\n① ○ 업무규정 제64조②3호는 「외국 국영기업의 경영자」를 명시하고 있으므로 외국 국영기업 자체가 고객인 경우는 3호에 포함되지 않는다. 6호의 「정치적 주요인물과 관련되어 있는 사업체 또는 단체」도 고객이 외국 국영기업이라는 이유만으로 해당한다고 보기 어렵다(유권해석사례집 2.0 사례73). 따라서 그 이유만으로 제66조의 고위경영진 승인 대상이 되는 것은 아니다.\n② ○ 6호의 「사업체 또는 단체」는 PEP가 그 사업체·단체에 직접적인 관련성(예: 실제 소유자에 해당하는 경우 등)을 갖는 경우를 말하며, 사정을 종합적으로 고려해 판단한다(사례73).\n③ ○ 「FATF 지정 위험국가의 국적자 또는 거주자」(업무규정 제43조①3호)에는 그 국가의 국적을 보유한 개인뿐 아니라 그 국가의 법령에 따라 설립된 법인 등 그 국가에 기반을 둔 법인·금융회사도 포함된다(사례72). FATF 지정 위험국가의 국적자 또는 거주자인 고객에게는 강화된 고객확인과 강화된 모니터링을 지속적으로 실시해야 한다(사례71, 업무규정 제72조①).\n④ ○ 「고위경영진」은 금융회사등의 영업 성질, 규모 등 구체적 상황을 고려해 결정할 사항이나, 자금세탁/테러자금조달 방지 주요 정책 결정 권한이 있고 위험 이해도가 높은 자를 요건으로 하며, 은행법상 은행의 경우 금융회사지배구조법상 임원급 이상의 준법감시인을 예로 든다(사례72).\n⑤ ✕ 고위험 고객에 대한 추가 확인사항은 「금융거래의 종류」에 따라 구분하고 있지 않으므로 대출고객이라고 거래자금의 원천 항목을 생략할 법적 근거는 없다. 대출고객도 거래자금의 원천을 확인해야 하며, 「기타(은행의 대출금)」 등으로 작성할 수 있다(사례70, 특금법 제5조의2①2호나목, 업무규정 제42조①②).\n함정: 「대출은 은행 돈이니 자금원천 확인 불필요」, 「국영기업 = 곧 PEP」, 「대표가 한국인이면 위험국가 고객 아님」. 고객의 형식(대출·국영기업·대표자 국적)이 아니라 규정의 문언과 실질 관련성으로 판단한다.",
