  "ex": "정답 2개(ㄷ·ㄹ).\nㄱ ✕ 집합투자업자는 특금법 제2조제1호마목의 금융회사등이다. 펀드를 직접 판매하지 않는다는 이유로 의무 적용을 제외할 수 없다(유권해석 사례3).\nㄴ ✕ 투자일임업자도 시행령 제2조제3호의 금융회사등이므로 고객확인 의무를 진다. 증권사가 이미 고객확인을 했다는 사실만으로 면제되지 않는다(사례4).\nㄷ ○ 증권사와 고객확인 업무 위수탁 계약을 따로 체결하고 업무규정 제53조 요건(정보 즉시 제공, 요청 시 문서사본 지체 없이 제공, 제3자가 감독을 받고 고객확인 조치를 마련했는지 확인 등)을 충족하면 제3자를 통한 고객확인이 가능하다. 그래도 최종책임은 위탁한 투자일임업자에 있다(업무규정 제52조~제54조, 사례4).\nㄹ ○ 신탁업자는 특금법 제2조제1호마목의 금융회사등이다. 여수신 업무 수행 여부와 자금세탁방지 의무는 직접 관련이 없고, 각 의무 주체가 자기 고객을 확인해야 한다(사례5).\nㅁ ✕ 자산규모 500억원 미만이라 시행령 제2조제14호(대부업자)에는 해당하지 않는다. 그러나 금융지주회사(시행령 제2조제7호)의 자회사(상법 제342조의2)이므로 시행령 제2조제15호·감독규정 제1조의2에 따라 금융회사등이다.\n함정: 「업권별 요건(자산규모)에 미달하면 의무 없음」에서 멈추지 말고, 금융회사등의 자회사인지 한 번 더 확인한다.",
