  "scene": "청룡카지노(「관광진흥법」에 따라 허가를 받은 카지노사업자) 자금세탁방지팀은 2026.11.3(화) 거래분을 점검하고 있다.\n1) 고객 A는 14:00 현금 1,500만원을 맡기고 보관 목적의 「보관증」을 받았다. A는 게임을 하지 않고 18:00 보관증을 반납하고 현금 1,500만원을 돌려받았다. 이런 일이 10월에도 다섯 차례 있었다.\n2) 고객 B는 11.2(월) 현금 1,200만원을 맡기고 받은 보관증을 11.3 제시하고, 그 대신 칩 1,200만원어치를 받았다. B는 11.3 다른 거래가 없다.\n3) 청룡카지노는 11.3 영업 마감 후 영업현금 2억원을 거래은행인 을은행 본사 계좌에 현금으로 입금했다. 을은행 CTR 담당자는 「청룡카지노도 특정금융정보법상 금융회사등」이라는 이유로 이 입금을 CTR 대상에서 빼려 한다.",
