  "ex": "정답 ④(ㄱ, ㄴ).\nㄱ ○ 카지노사업자의 금융거래등은 영업장에서 현금·수표를 대신해 쓰이는 칩(베팅 도구)과 현금·수표를 교환하는 거래다(특금법 제2조제2호다목, 시행령 제3조②). 보관 목적의 현금↔보관증 교환은 이에 해당하지 않아 CTR 대상이 아니다(TPAC 07 CTR 유권해석 4. 카지노사업자의 업무).\nㄴ ○ 현금을 영수하고 발행해 준 보관증을 받고 칩을 지급하는 행위는 다른 요건을 충족하면 CTR 대상이 될 수 있다. 카지노는 1거래일 합산이 아니라 1건당 금액 기준이고, 1,200만원은 기준금액(1천만원) 이상이다(TPAC 07 유권해석 4·보고대상 거래일).\nㄷ ✕ CTR 대상 여부와 STR은 별개다. 유권해석도 보관증 거래가 CTR 대상이 아니더라도 카지노사업자는 고객확인을 하고 자금세탁 등이 의심되는 합당한 근거가 있으면 FIU에 보고하는 등 의무를 성실히 이행해야 한다고 한다(특금법 제4조①, TPAC 07 유권해석 4). STR은 기준금액도 없다(TPAC 08).\nㄹ ✕ 다른 금융회사등과의 현금 지급·영수는 CTR 면제지만, 카지노사업자·가상자산사업자 등은 그 면제에서 제외된다(특금법 제4조의2①1호, TPAC 07 CTR보고 면제 대상). 을은행은 이 입금을 보고해야 한다.\n함정: 「카지노도 금융회사등」→「금융회사 간 거래라 면제」로 곧장 잇지 않는다. 카지노는 면제의 예외다. 또 「CTR 아님」을 「STR도 아님」으로 확장하지 않는다.",
  "src": "특금법 제2조제2호다목 · 제4조① · 제4조의2① · 시행령 제3조② · TPAC 핵심포인트 07(CTR보고 면제 대상 · 보고대상 거래일 · 유권해석 4. 카지노사업자의 업무) · TPAC 핵심포인트 08(STR 기준금액 폐지)",
