  "scene": "해오름카지노(「관광진흥법」에 따라 허가를 받은 외국인 전용 카지노사업자)의 자금세탁방지팀장 R은 2026년 10월 시중은행 자금세탁방지부에서 옮겨 왔다. R은 2026.11.2(월)~11.6(금) 고객확인 처리 건을 점검하면서 다음과 같이 판단했다.\n(가) 국내에 거주하며 외국인등록을 한 F는 자금세탁 위험이 낮은 고객으로 평가되었다. 직원은 F의 여권으로 신원을 확인하고, 별도의 검증 서류를 받지 않았다.\n(나) 고객 G는 11.3~11.5 사흘 동안 칩 교환을 다섯 번 했다. 건별 금액은 모두 일회성 금융거래 기준금액보다 조금 적었지만, 합하면 기준금액의 네 배가 넘는다.\n(다) 고객 H는 신원정보 제공을 거부해 직원이 거래를 거절했다.\n(라) A국 국적 J는 8개월 전 A국 장관직에서 물러났다. J가 칩 교환을 신청했다.\n(마) 별도 게임장을 이용하는 VIP 고객 K는 「추가정보 확인이 필요한 고객」으로 선정되었고, 자금세탁 위험이 특히 높다고 평가되었다.",
