  "ex": "정답 3개(ㄱ·ㄹ·ㅁ).\nㄱ ○ 카지노사업자는 위험이 낮은 경우로서 외국인에 대해 여권 등으로 신원을 확인한 때 검증을 이행한 것으로 볼 수 있다(업무규정 제116조②3호). 금융회사등(제1편)의 같은 조항(제39조②)에는 이 여권 호가 없다. F는 거주자라 비거주자 고위험군(제108조②3호)에도 해당하지 않는다.\nㄴ ✕ 7일 합산 「연결거래」는 제1편(카지노사업자 제외) 제23조②의 규정이다. 카지노사업자의 일회성 금융거래는 건별로 기준금액 이상인 거래를 말한다(제104조). 다만 자금세탁이 의심되면 금액과 무관하게 고객확인을 해야 하고(제105조①), 기준금액 바로 아래로 나눈 칩 교환은 카지노 의심거래 유형이므로 STR 여부를 검토해야 한다(TPAC 08 카지노업 참고유형).\nㄷ ✕ 카지노사업자는 고객확인을 할 수 없어 거래를 거절한 때 의심거래보고를 「검토」해야 한다(업무규정 제120조, 특금법 제5조의2⑤). 「반드시 보고」는 제1편 금융회사등의 제44조① 문언(「이행하여야」)을 옮겨 온 것이다.\nㄹ ○ 카지노 업무규정의 외국의 정치적 주요인물은 현재 또는 과거(일반적으로 사임 후 1년 이내)에 외국에서 정치적·사회적 영향력을 가진 자다(제126조①②1호). 8개월 전 사임한 장관은 해당하며, 카지노사업자가 이들과 금융거래를 하려면 고위경영진의 승인을 얻어야 한다(제128조).\nㅁ ○ 특별한 서비스를 받는 고객 중 위험이 특히 높은 고객은 금융거래 승인부서와 독립된 부서의 「상위 책임자」가 지속적으로 모니터링해야 한다(제125조②). 제1편(제63조②)에는 「상위 책임자」 문언이 없다.\n함정: 은행 규정(연결거래, STR 「이행」)을 카지노에 그대로 옮기는 착각. 카지노 PEP는 「사임 후 1년 이내」가 붙는다.",
