  "scene": "무진은행 자금세탁방지팀은 2026.11.5(목) 다음 네 건을 처리하고 있다.\n1) 법인 고객 甲사는 2024년 이후 세 차례 의심거래로 보고되었다. 팀장은 「최근 3년 안에 3회 이상 의심거래보고된 고객은 거래를 종료한다」는 본점 내규에 따라 甲사에 거래 종료를 통지하려 한다.\n2) 무진금융그룹은 금융범죄로 거래를 끝낸 법인을 그룹 공동의 Global Exit List에 올린다. 팀은 甲사의 법인명·법인설립일·법인등록번호(모두 법인등기부등본에 나오는 정보)만 등록하고, 의심거래보고 여부나 그 내용은 등록하지 않기로 했다.\n3) 개인 고객 乙(주부)은 지난 6개월 동안 매달 2천만원 안팎의 현금을 무진은행 창구에서 은행지로로 자녀·친척 명의 보험료로 납부했다. 담당자는 「은행지로 거래는 고객확인·고액현금거래보고 대상이 아니다」라며 의심거래 검토 없이 종결했다.\n4) 甲사의 세무 자문을 맡은 세무사 丙이 자문 과정에서 甲사 자금이 불법재산이라고 의심할 정황을 알고도 FIU나 수사기관에 알리지 않은 사실이 드러났다.",
