  "ex": "정답 ①(ㄱ, ㄴ).\nㄱ ○ 유권해석: 의심거래보고 고객의 거래 종료는 특정금융정보법이 따로 정하지 않으므로, 「3년 내 3회 이상 보고 고객 거래 종료」는 특정금융정보법 및 관련 규정에 근거가 있지 않다고 보인다(TPAC 08 STR Q&A 1). 법이 거래 거절·종료를 정한 것은 고객확인을 할 수 없는 경우 등이다(특금법 제5조의2④).\nㄴ ○ 유권해석: 공유되는 정보가 법인등기부등본상 공개정보이고 의심거래보고 여부나 내용, 이를 추정할 수 있는 정보가 공유되지 않는 한 GEL 등록은 제4조⑥ 위반이 아니다(TPAC 08 STR Q&A 2).\nㄷ ✕ 은행지로는 CDD·CTR 대상이 아니지만, 공과금으로 보이지 않는 거액을 지로로 거래하면 의심거래로 보고해야 한다. 고액 보험료를 현금으로 지로 납부하는 사례가 실제로 지적되었다(TPAC 08 STR Q&A 6, TPAC 02 보험업 취약점). STR은 기준금액도 없다.\nㄹ ✕ 의심거래보고 의무는 특금법 제2조제1호의 금융회사등에 부과되고, 변호사·세무사는 여기에 포함되지 않는다. 따라서 丙에게 특금법상 신고·고발 의무는 없다(특금법 제2조제1호·제4조①, TPAC 08 STR Q&A 9).\n함정: 「CTR·CDD 대상 아님」을 「STR 검토도 불필요」로 넓히는 착각, 그리고 고객 관련 전문직에게 금융회사등의 STR 의무를 씌우는 착각.",
