  "ex": "정답 ②.\n① ○ PG·에스크로는 판매점(Seller)에 대해 CDD를 이행하고, 구매자(Buyer)는 대부분 은행·카드사 고객으로 CDD를 이미 이행한 점에서 면제된다. 최근 대형 전자금융업자는 구매자에게도 CDD를 이행하는 추세다(TPAC 02 전자금융업자의 자금세탁방지의무).\n② ✕ 전자화폐·선불전자지급수단의 발행권면 최고한도와 관계없이 충전과 양도를 반복하면 자금 이체가 제한 없이 가능하다는 것이 전자금융업자의 대표적 자금세탁 취약점이다(TPAC 02 전자금융업자의 자금세탁 취약점). (가)는 오히려 보고서에 적고 STR 여부를 검토해야 할 패턴이다.\n③ ○ 위험이 낮은 무기명 전자화폐와 선불전자지급수단 발행 시에는 고객확인의 전부 또는 일부를 생략할 수 있으나, 고위험 고객은 예외 없이 강화된 고객확인이 필요하다(TPAC 02).\n④ ○ 전자금융업자는 고객확인 신원확인정보의 주민등록번호를 CI로 대체 관리할 수 있으나, 개인의 성명·생년월일·성별, 주소·연락처, 전자금융거래용 계좌번호(또는 참조번호)는 확인해야 한다(TPAC 02).\n⑤ ○ 자금 이동경로 추적의 어려움과 비대면 거래에 따른 정확한 고객확인의 한계는 전자금융업자의 자금세탁 취약점으로 제시된다(TPAC 02).\n함정: 「발행 한도가 있으니 안전」이라는 착각. 한도는 1회 발행권면의 상한일 뿐 충전·양도 반복을 막지 못한다.",
