  "scene": "정은행 거래모니터링팀 조사자 M은 2026.11.6(금) 법인 고객 한빛귀금속(주)(금 도매업)의 의심거래보고서를 쓰고 있다.\n1) 정은행은 2026.5.12(화) 한빛귀금속의 같은 유형 거래를 이미 의심거래로 보고했고, 그 뒤에도 같은 유형의 거래가 계속되어 이번이 반복 보고다.\n2) 2026.8월~10월 의심되는 거래는 모두 15억원이다. 이 중 2억 4천만원은 한빛귀금속이 계좌에서 거래처로 보내는 이체를 「현금으로 처리해 달라」고 요청해 원장상 현금으로 처리된 거래다.\n3) 2026.10.20(화) 검찰청이 횡령 혐의로 발부받은 한빛귀금속 관련 압수수색영장(문서번호 ○○○)이 정은행에 접수되었다.\n4) 같은 기간 한빛귀금속 법인 계좌와 대표이사 개인 계좌 사이에 양방향 이체가 잦았다.\n5) 한빛귀금속은 홍콩 소재 법인에 미화(USD)로 여러 차례 해외송금을 했다.\nM은 보고서 작성 전에 아래 메모를 정리했다.",
