  "ex": "정답 3개(ㄱ·ㄴ·ㄷ).\nㄱ ○ 고객 요청에 의한 (대체거래 현금처리)의 경우 해당 패턴으로 거래된 금액(전체 거래금액이 아님)을 제목에 바로 기재하고, 금액은 백만원 단위로 통일한다(TPAC 08 STR 작성시 참고사항 — 제목 나.3)·거래내역 1).\nㄴ ○ 법집행기관 등과 공유(영장청구, 정보제공 요청 등)된 거래건은 (영장등관련건/요구기관/문서번호/요구일자/전제범죄) 형식으로 통일하여 기재한다(같은 참고사항 — 제목 다.). 영장 접수로 횡령 연관을 알게 된 거래 자체도 STR 대상이다(TPAC 08 제2장 5.).\nㄷ ○ 법인-대표자(직원) 거래는 일정 기간 중 ①법인→대표자, ②대표자→법인, ③순 유출(유입) 금액을 파악하여 함께 기재한다(같은 참고사항 — 거래내역 6.).\nㄹ ✕ 2026.5.12 최초 보고 후 약 6개월이 지나 3개월을 초과해 지속·반복 보고하는 건이다. 이 경우 최근 3개월 거래규모와 함께 최초 보고 이후 누적 거래규모를 최근 3개월·6개월·12개월 순으로 기재한다(같은 참고사항 — 3. 나.).\nㅁ ✕ 환거래는 외화금액과 원화 환산금액을 함께 병기한다(같은 참고사항 — 거래내역 6.). 백만원 단위 통일은 원화 금액 표기 원칙일 뿐 외화 금액을 빼라는 뜻이 아니다.\nㅂ ✕ 금융회사가 직접적인 관련인일 경우 외에는 금융회사를 관련인에 넣는 것은 지양한다(같은 참고사항 — 거래자 3.).\n함정: 「3개월 총액」 규칙을 최초 보고 시점과 무관하게 적용하는 것, 그리고 「백만원 단위 통일」을 「외화 금액 생략」으로 확장하는 것.",
