  "p": 15,
  "scene": "갑은행(「은행법」에 따른 은행) 자금세탁방지팀은 2026.11.6(금) 가상자산 관련 고객을 점검하고 있다. 2026.8.20 시행된 개정 특정금융정보법을 반영해야 한다.\n(가) 을사: 원화마켓 가상자산거래소. 신고가 수리되어 영업 중이며, 갑은행이 실명확인 입출금계정을 제공하고 있다.\n(나) 병사: 가상자산거래소를 새로 열기 위해 금융정보분석원장에게 처음 신고하려고 준비 중이며, 갑은행에 실명확인 입출금계정 개설을 문의했다. 병사의 의결권 있는 발행주식은 개인 Y가 35%(최대주주), 개인 Z가 12%를 각자 자기 명의·자기 계산으로 보유한다(Y와 Z는 서로 특수관계인이 아니다). Y는 대표자도 임원도 아니다.\n(다) Y는 2023년 X국에서 우리 「자본시장과 금융투자업에 관한 법률」에 상당하는 X국 증권법 위반으로 벌금형을 선고받았고, 2023.6월 벌금 납부를 마쳤다.",
