  "ex": "정답 ①(ㄱ, ㄷ, ㄹ).\nㄱ ○ 「대주주」에는 최대주주뿐 아니라, 누구의 명의로 하든지 자기의 계산으로 가상자산사업자의 의결권 있는 발행주식 총수의 100분의 10 이상을 소유하는 주요주주가 포함된다(특금법 제2조제7호나목1), 2026.8.20 시행).\nㄴ ✕ 개정법은 불수리 사유의 범위를 「이에 상당하는 외국의 관련 법률」로 넓히고, 가상자산사업자가 법인인 경우 그 대표자·임원뿐 아니라 대주주까지 포함한다(제7조③3호). Y는 최대주주이므로 대주주이고(제2조제7호가목), 자본시장법에 상당하는 외국 법률로 벌금형을 받아 집행이 끝난 날(2023.6월)부터 5년이 지나지 않았으므로 불수리 사유에 해당할 수 있다.\nㄷ ○ 금융정보분석원장은 신고 또는 변경신고를 수리하는 경우 자금세탁행위와 공중협박자금조달행위의 방지, 금융거래 질서 확립, 가상자산 이용자 보호 등을 위하여 필요한 조건을 붙일 수 있다(제7조⑩, 2026.8.20 시행).\nㄹ ○ 가상자산사업자인 고객의 신고 또는 변경신고가 직권으로 말소된 사실이 확인되면 금융회사등은 거래를 종료하여야 하고(제5조의2④2호라목), 이 경우 의심되는 거래의 보고 여부를 검토하여야 한다(같은 조 ⑤).\nㅁ ✕ 미신고 영업은 5년 이하 징역 또는 5천만원 이하 벌금(제17조①)이지만, 변경신고를 하지 않은 자는 3년 이하의 징역 또는 3천만원 이하의 벌금이다(제17조②).\n함정: 개정 전 기준(국내 법률·대표자·임원만)으로 불수리 사유를 판단하는 것, 그리고 미신고와 변경신고 미이행의 벌칙을 같게 보는 것.",
