  "scene": "정금융그룹 자금세탁방지협의회는 2026.11.6(금) 계열사들이 올린 고객확인 사례를 검토했다.\n(가) 정은행: 부동산 개발사업을 위해 설립된 SPC 갑유동화(유한회사, 직원 없음)가 대출 약정을 신청했다. 대출금은 실제로 시행사 을건설의 사업에 쓰이고, 을건설이 갑유동화를 사실상 지배한다.\n(나) 정캐피탈(시설대여업자): A법인 직원이 「대표자 甲이 실제로 탈 차량」이라며 A법인 명의로 금융리스 계약을 신청했다. 같은 날 B법인과는 건설장비 운용리스 계약을 체결했다.\n(다) 정증권: 외국인 투자등록제 폐지 후 외국 금융회사 V가 여러 최종투자자의 주문을 모아 처리하는 통합계좌 개설을 신청했다. V는 FATF 상호평가에서 효과적인 자금세탁방지 체계를 갖춘 것으로 확인된 국가에 소재하고, 최종투자자에 대한 고객확인을 FATF 권고기준에 따라 이행하며, 소재국 금융당국으로부터 충실히 감독·모니터링을 받고 관련 제재를 받지 않은 사실을 증빙했다. 정증권은 V에 대한 신원확인을 적절히 마쳤다.",
