  "a": 4,
  "ex": "정답 ⑤.\n① ✕ 대출계약에서 금융거래를 개시할 목적으로 금융회사등과 계약을 체결하는 자가 고객이므로 고객확인 대상은 SPC(갑유동화)이다. 다만 고객을 최종적으로 지배·통제하는 사람이 실제 대출자라면 실제소유자 확인 시 실제 대출이 집행되는 회사(을건설)와 그 회사의 실제소유자를 확인할 수 있다(유권해석사례집 2.0 사례60, 특금법 제5조의2①1호, 시행령 제10조의2②).\n② ✕ 시설대여업자가 리스계약을 체결하는 것은 금융거래 개시 목적의 계약 체결에 해당하므로 운용리스에도 고객확인의무가 적용되고, 실제소유자도 확인해야 한다(사례62).\n③ ✕ 고객확인은 계약명의자인 A법인을 상대로 해야 한다. 그 과정에서 고객을 최종적으로 지배·통제하는 사람이 있으면 실제소유자로 확인하며, 대표자 甲이 이에 해당할 여지가 있다(사례61).\n④ ✕ 통합계좌는 명의자(V)를 고객으로 하여 고객확인의무를 이행한다(사례69).\n⑤ ○ 통합계좌의 실제소유자는 원칙적으로 최종투자자이나, ①국내 금융회사가 명의자 신원확인을 적절히 이행하고 ②명의자가 FATF 상호평가상 효과적 체계를 갖춘 국가 소재 외국 금융회사이며 ③최종투자자 고객확인을 FATF 권고기준에 따라 이행하고 ④소재국 금융당국의 감독을 받고 제재를 받지 않은 사실이 증빙되면 최종투자자에 대한 실제소유자 확인의무가 면제될 수 있다(사례69). 사례는 네 요건을 모두 갖췄다.\n함정: 「돈이 실제로 누구에게 가는가」로 고객(계약 당사자)을 바꾸는 것. 고객은 계약명의자이고, 실질 지배자는 실제소유자 확인 단계에서 잡는다.",
