  "scene": "무진저축은행(「상호저축은행법」에 따른 상호저축은행) 자금세탁방지팀은 2026.11.4(수) 금융정보분석원(FIU)으로부터 2026년 상반기 위험관리수준 평가(제도이행평가) 결과를 받았다. 결과는 고유위험 「다소 높음」, 운영위험 「미흡」이었다.\n평가지표는 담당자 L이 전산에서 데이터를 추출해 FIU 위험평가시스템에 입력했었다.\n팀장 J는 2026.11.10(화) 이사회 보고자료에 평가 체계와 후속 조치를 아래와 같이 정리했고, 보고책임자 K는 원문과 맞지 않는 문장을 고르라고 지시했다.",
