  "a": 3,
  "ex": "정답 ㄱ, ㄴ, ㅁ.\nㄱ ○ 고유위험(높음/다소 높음/보통/다소 낮음/낮음)과 운영위험(우수/양호/보통/미흡/주의)을 각각 5단계로 등급화하고, 각 등급별 위험도를 평가해 집중감시·일상감시·자율감시로 등급화하여 검사수탁기관이 활용할 수 있게 한다. 다만 검사수탁기관의 활용 여부는 자체 결정에 따라 다를 수 있다(TPAC 핵심포인트 03 「제도이행평가 결과」).\nㄴ ○ 제도이행평가는 위험노출정도에 비례하여 위험관리수준을 갖추고 대응하는지에 대한 평가 체계이며, 위험노출정도가 높은데 위험관리수준이 낮게 평가되면 고위험 금융회사등으로 평가된다(TPAC 핵심포인트 03 「제도이행평가 개요」).\nㄷ ✕ 데이터를 전산에서 추출해 입력할 경우 추출 로직의 무결성 검증절차를 마련하고, 지표 입력내용 등의 증빙자료(데이터 추출 로직 포함)는 내·외부 검사 대비 등을 위해 보관·관리해야 한다(TPAC 핵심포인트 03 「제도이행평가지표 및 입력」).\nㄹ ✕ FIU원장은 위험관리수준 평가 결과를 검사수탁기관의 장과 공유하고 감독·검사·교육에 활용하여야 하며, FIU원장과 검사수탁기관장은 검사계획 수립, 검사의 강도·빈도 결정 시 금융회사등의 위험 특성 평가로 파악한 위험 등을 고려하여야 한다(업무규정 제19조⑥).\nㅁ ○ FIU원장과 검사수탁기관장은 위험관리수준 평가 등에 기반한 주기적 점검·검사를 실시하고, 경영 또는 운영 관련 중요한 사안이 발생했을 때에는 적시에 점검 및 검사를 실시하여야 한다(업무규정 제19조⑦).\n※ ㄱ과 ㄹ은 충돌하지 않는다: 3단계 감시 등급의 「활용」은 수탁기관 자율이지만, 평가 결과의 공유와 검사계획·강도·빈도 결정 시 위험 요소의 「고려」는 업무규정 제19조⑥의 의무다.\n함정: 「평가 결과 = FIU 내부자료」로 보고 검사계획과의 연결(제19조⑥)을 끊는 것, 「입력했으니 증빙 불필요」. 반대로 감시 등급의 「활용 여부」는 검사수탁기관 자율이라는 단서도 함께 기억할 것.",
