  "scene": "금융정보분석원(FIU) 기획행정실은 2026.11.9(월) 특정금융거래정보의 제공·관리 업무를 자체 점검했다. 점검 대상은 다음과 같다.\n1) 2026.10.20 관세청장이 관세탈루혐의 확인 조사를 위해 갑에 대한 정보(특금법 제10조제1항제3호에 규정된, 보고·통보받은 정보를 정리·분석한 정보)의 제공을 문서로 요구했다. 문서에는 대상자의 인적사항, 사용 목적, 요구하는 정보의 내용만 적혀 있었다.\n2) 2026.3.2 정보분석심의회 심의를 거쳐 경찰청장에게 을에 대한 특정금융거래정보를 제공했다.\n3) 정보분석심의회 구성 방식을 바꾸는 내부 개선안 초안이 올라왔다.\n4) 2)와 별도로 2026.4월 FIU로부터 병에 대한 특정금융거래정보를 제공받은 검찰 수사팀이, 그 정보를 병의 형사재판에 증거로 낼 수 있는지 문의했다.\n5) FIU가 보존해 온 정보 가운데 보존기간이 지난 정보가 있다.",
  "ask": "점검 결과로 옳은 것은 모두 몇 개인가?",
