  "ex": "정답 2개(ㄱ·ㄹ).\nㄱ ○ 관세청장은 검찰총장등에 포함되어 특정형사사건의 수사등을 위해 제10조제1항제3호의 정보 제공을 요구할 수 있으나(특금법 제10조④), 요구 문서에는 ①대상자의 인적사항 ②사용 목적 ③요구하는 정보의 내용 ④범죄혐의와 조세탈루혐의 등 정보의 필요성과 사용 목적과의 관련성을 모두 적어야 한다(제10조⑤). 이를 위반한 요구를 받은 FIU 소속 공무원은 거부하여야 한다(제10조⑥).\nㄴ ✕ 제공 기록은 표준양식으로 제공한 날부터 5년간 기록·보존한다(제10조⑦).\nㄷ ✕ 정보분석심의회는 FIU원장과 심사분석 총괄책임자를 포함한 FIU 소속 공무원 3명으로 구성하고, 나머지 1명은 대통령령으로 정하는 자격을 가진 사람으로 한다(제10조⑨). 외부 민간위원으로 구성하는 것은 법문과 다르다.\nㄹ ○ 제10조에 따라 제공된 특정금융거래정보는 재판에서 증거로 할 수 없다(제12조③).\nㅁ ✕ 보존기간이 지나면 공공기록물법 절차에 따라 폐기하되(제12조의2②), 폐기하는 때에는 복구 또는 재생되지 아니하도록 조치하여야 한다(같은 조 ③).\n함정: 요구 문서 기재사항 4가지 중 하나만 빠져도 거부 사유, 기록 보존기간 숫자(5년), 「심의회 = 외부위원 포함」이라는 막연한 상식, 폐기 후 복구 방지 의무.",
