  "scene": "무궁금융그룹은 국내 은행인 무궁은행을 중심으로 한 금융그룹이다. 무궁은행은 X국(FATF 상호평가에서 효과적인 자금세탁방지 체계를 갖춘 것으로 확인된 국가)에 지배지분 100%를 보유한 증권 자회사 무궁증권X를, Y국에 지점을 두고 있다.\nY국의 자금세탁방지·테러자금조달금지(AML/CFT) 최소요건은 한국보다 덜 엄격하고, Y국 법령은 Y국 지점이 한국 요건 일부를 적절히 이행하는 것을 허용하지 않는다.\n그룹 AML 총괄팀은 2026.11.9(월) FATF 권고기준 제17조(제3자 의존)와 제18조(내부통제와 해외 지점·자회사)를 기준으로 다음 두 안건을 검토했다.\n(가) X국 거주 고객이 무궁은행에 계좌 개설을 신청하자, 무궁증권X가 이미 이 고객에 대해 수행한 고객확인에 의존하려는 안\n(나) Y국 지점의 AML/CFT 관리 방안",
