  "ex": "정답 ⑤.\n① ✕ 제3자에게 고객확인을 의존(위탁)하는 것이 허용되더라도 고객확인 조치에 대한 최종책임은 위탁한 금융기관에 있다(FATF 권고기준 제17조, 업무규정 제54조). 같은 그룹 계열사라도 마찬가지다.\n② ✕ 같은 금융그룹 계열사에 의존하는 특례는 (i) 그룹이 권고사항 10·11·12에 따른 고객확인·기록보존 의무와 권고사항 18에 따른 AML/CFT 프로그램을 실시하고 (ii) 그 효과적 이행을 권한당국이 그룹 차원에서 감독하는 경우에 한해, 요건 (b)·(c)를 충족한 것으로 볼 수 있게 한다. 국가위험 고려 요건 (d)는 더 높은 국가위험이 그룹 AML/CFT 정책으로 적절히 경감되는 경우에만 필수 전제조건이 아니라고 판단할 수 있다(FATF 권고기준 제17조 주석).\n③ ✕ 현지 국가의 AML/CFT 최소요건이 본사 국가보다 덜 엄격하면, 금융기관은 현지 지점과 지배지분 보유 자회사가 현지 법규가 허용하는 범위에서 본사 국가의 요건을 이행하도록 해야 한다(FATF 권고기준 제18조 주석 5; 국내는 업무규정 제27조③).\n④ ✕ 현지 국가가 본사 국가 요건의 적절한 이행을 허용하지 않으면, 금융그룹은 위험을 관리하기 위한 적절한 추가적 조치를 적용하고 본사 국가 감독관에게 알려야 한다. 추가적 조치가 충분하지 않을 때 본사 국가 권한당국이 현지 영업 정지 요구 등 추가적 감독행위를 고려한다(FATF 권고기준 제18조 주석 5; 국내는 업무규정 제27조④).\n⑤ ○ 금융그룹의 AML/CFT 프로그램은 모든 지점과 지배지분 보유 자회사에 적용되어야 하고, 고객확인과 ML/TF 위험관리를 위한 정보공유 정책·절차를 포함해야 하며, 필요한 경우 그룹 차원의 법규 준수·감사·AML/CFT 기능을 위해 지점·자회사로부터 고객·계좌·거래정보를 제공받되 비밀보장과 교환된 정보 이용에 대한 적절한 보호장치를 마련해야 한다(FATF 권고기준 제18조 주석 4).\n함정: 「같은 그룹이면 책임도 넘어간다」, 「그룹 특례 = 무조건 요건 충족」, 「현지법만 지키면 된다」, 「이행 불가 = 즉시 철수」. 순서는 본국 요건 이행 → 안 되면 추가 조치 + 본국 감독관 통지 → 그래도 부족하면 감독당국이 영업정지 등 고려.",
