  "scene": "늘봄은행 자금세탁방지부는 2026.11.9(월)~11.11(수) 고액현금거래보고(CTR) 업무를 자체 점검하고 다음 사실을 확인했다.\n1) 창구 직원들이 계좌에서 계좌로 옮기는 대체거래를 기표 편의상 「현금」으로 처리하는 일이 잦아, 매일 수십 건이 CTR 대상으로 추출된 뒤 자금세탁방지부가 수작업으로 보고 대상에서 빼고 있다.\n2) 고객 Y의 10.20 CTR 보고 내역에, 같은 날 창구 현금 입금 1,200만원과 함께 스마트뱅킹 가입 인증을 위해 다른 은행 계좌에서 이체받은 1원이 현금 입금으로 분류되어 들어가 있었다.\n3) CTR 자료는 전산이 매일 자동으로 FIU에 전송하고, 보고책임자는 전송이 끝난 다음 날 그 목록을 일괄 결재한다.\n4) 늘봄은행과 제휴한 우체국 창구에서 고객 W가 늘봄은행 본인 계좌에 현금 1,500만원을 입금했다.\n5) 법인 고객 Z는 자기 계좌의 1,300만원을 거래처 계좌로 보내면서 「현금으로 처리해 달라」고 요청했고, 실제 현금 이동은 없었다. 늘봄은행은 이 거래를 CTR 보고에서 제외했지만, 의심거래보고(STR) 여부를 검토한 내용을 문서로 남기는 절차는 없다.",
  "ask": "점검 의견 중 옳은 것만을 모두 고른 것은?",
