  "a": 0,
  "ex": "정답 ㄱ, ㄷ, ㅁ.\nㄱ ○ 현금의 물리적 이동이 없는 대체거래를 전산처리 편의상 현금거래로 처리한 뒤 사후에 CTR 대상에서 빼는 건이 과다하면 CTR 업무의 효율성·정확성이 저해되므로, 현금거래가 아닌 거래가 CTR 대상으로 추출되지 않도록 전산처리 절차를 개선해야 한다는 것이 FIU의 지적사항이다(TPAC 핵심포인트 07 「CTR 관련 주요 지적사항」 (1)·(5)1)).\nㄴ ✕ CTR은 금융회사와 고객 사이의 현금의 물리적 이동을 보고하는 제도이고, 계좌이체 등 회계상 가치이전만 있는 거래는 대상이 아니다(TPAC 07 Q&A 1). 스마트뱅킹 가입 후 이체 테스트용 1원 입금이 FIU에 보고된 것은 「현금의 물리적 이동이 없는 끝전거래」의 오류 보고로 지적된 사례다(지적사항 (5)1)). 보고된 CTR 정보는 법집행기관에 제공되면 명의인에게 통보되므로, 이미 보고한 오류 건은 점검해 취소(정정)보고해야 한다(지적사항 (4), 특금법 제10조의2①).\nㄷ ○ CTR이 이미 이행된 뒤 보고책임자가 결재하는 방식은 보고책임자의 적정성 검토가 사전에 이루어지지 않아 프로세스 개선이 요구된다(TPAC 07 지적사항 (5)5)). 보고책임자는 고액현금거래를 FIU원장에게 보고하는 자다(업무규정 제6조①).\nㄹ ✕ 우체국과 제휴한 금융회사의 계좌 거래는 해당 계좌개설 금융회사가 우체국으로부터 데이터를 받아 CTR 보고의무를 이행한다(TPAC 07 Q&A 30). 계좌거래의 CTR 보고 주체는 계좌개설 금융회사, 보고대상 거래자는 계좌명의인이다(TPAC 07 「보고의무의 주체와 거래상대방」). 늘봄은행이 W의 1,500만원 현금 영수를 보고해야 한다.\nㅁ ○ 「고객의 현금처리 요청」처럼 현금의 물리적 이동이 없는 거래는 원장에 현금으로 표기되었더라도 CTR에서 제외하되, 고객의 의도 등을 감안해 STR 여부를 적극 검토해야 한다(TPAC 07 지적사항 (3)). 대체거래를 고객 요청에 따라 현금거래로 처리하는 경우 STR 검토 내용을 문서화하는 절차를 마련·운영하라는 것이 FIU 지적사항이다(TPAC 08 「STR관련 주요 지적사항」 3.(6)). 의심거래 미보고 대상에 대해 조사한 기록도 보존 대상이다(업무규정 제85조③3호).\n함정: 「계좌에 들어온 돈이니 정상 보고」(ㄴ), 「현금을 만진 창구 = 보고 주체」(ㄹ). CTR은 현금의 물리적 이동이 기준이고, 제휴 우체국 거래는 계좌개설 금융회사가 보고한다.",
