  "scene": "별빛카지노(「관광진흥법」에 따라 허가를 받은 카지노사업자, 영업장 2곳)는 2026.11.11(수) 2027년 자금세탁방지 내부통제 계획 초안을 검토하고 있다. 초안은 시중은행 자금세탁방지부에서 옮겨 온 직원 T가 은행 시절 관행을 참고해 작성했다.\n1) 감사위원회에는 자금세탁방지 경력이 있는 위원이 있어 직접 감사할 여건이 충분하지만, 독립적 감사는 외부 회계법인에 맡긴다.\n2) 본사 영업장은 연 1회 실지감사를 하고, 지방 영업장은 자금세탁 위험도가 낮다는 이유로 2년에 1회 서면·모니터링 방식으로만 감사한다.\n3) 감사위원회는 감사를 마친 뒤 결과를 이사회에 보고하고, 감사범위·내용·위반사항·사후조치를 기록·관리한다.\n4) 별도 게임장을 이용하는 고객 V를 11.9 「추가정보 확인이 필요한 고객」으로 선정했다. V는 그 뒤 아직 거래하지 않았으므로, V가 다음에 칩을 교환할 때 관리자의 검토·승인을 받기로 했다.\n5) 단체 관광객이 몰리는 시간대에 카지노 업무의 특성상 불가피하게 칩 교환을 먼저 처리하고 고객확인을 나중에 하는 경우에는 지체 없이 고객확인을 이행하고, 그 과정에서 생길 수 있는 자금세탁행위등의 위험을 관리·통제할 절차를 수립·운영한다.",
