  "ex": "정답 2개(ㄷ·ㅁ).\nㄱ ✕ 카지노사업자는 감사 또는 감사위원회로 하여금 독립적 감사를 실시하도록 하여야 하고(업무규정 제97조①), 감사부서 외의 내부부서나 외부전문가에게 맡길 수 있는 것은 감사 또는 감사위원회가 독립적 감사를 실시하기 「어려운 경우」에 한한다(제97조③). 감사위원회가 직접 할 여건이 충분한 1)은 해당하지 않는다. 금융회사등(제1편)은 이런 조건 없이 맡길 수 있다(제13조③) — T가 은행 기준을 옮겨 온 함정이다.\nㄴ ✕ 카지노사업자는 독립적 감사를 연 1회 이상(제98조), 실지감사의 방법으로(제99조①) 실시하여야 한다. 영업점에 대해 감사주기를 따로 정하고 서면·모니터링을 활용할 수 있다는 단서는 금융회사등에만 있다(제14조 단서, 제15조① 단서).\nㄷ ○ 카지노사업자의 감사 또는 감사위원회는 감사 후 결과를 이사회에 보고하고 감사범위·내용·위반사항 및 사후조치 등을 기록·관리하여야 한다(제100조).\nㄹ ✕ 카지노사업자는 추가정보 확인이 필요한 고객으로 「선정한 때」 강화된 고객확인으로 획득한 신원정보 등의 적정성과 거래의 수용여부에 대해 관리자의 검토·승인을 얻어야 한다(제124조②). 다음 거래 때로 미루는 것은 맞지 않다. 금융회사등은 선정·편입된 고객이 「계좌를 신규로 개설하는 때」 승인을 얻는다(제62조②) — 이 차이가 함정이다.\nㅁ ○ 카지노 업무의 특성 및 금융거래의 성질 등으로 불가피하게 금융거래 후 고객확인을 하는 때에는 지체 없이 이행하여야 하고, 그 경우 발생할 수 있는 자금세탁행위등의 위험을 관리·통제할 절차를 수립·운영하여야 한다(제111조①②).\n함정: 업무규정 제1편(금융회사등)의 완화 규정 — 외부감사 위탁(제13조③), 영업점 감사주기·서면감사(제14조·제15조 단서), 계좌개설 시 승인(제62조②) — 을 제2편(카지노사업자)에 그대로 옮기는 것.",
