  "scene": "새봄신용협동조합(조합원 대부분이 지역 주민·소상공인) 자금세탁방지팀은 2026.11.11(수) 연간 자금세탁 위험평가 보고서를 쓰면서 최근 사례를 정리했다.\n1) 인근 시중은행들이 보이스피싱 의심계좌 통제를 강화한 지난봄 이후, 새봄신협 계좌가 보이스피싱 피해금 이체에 쓰였다는 지급정지 요청이 크게 늘었다.\n2) 외국인 근로자 밀집지역에서 식료품점을 하는 조합원 H의 계좌에 매일 외국인 수십 명이 수십만원씩 입금한다. H의 계좌에서 해외로 나가는 송금은 한 건도 없는데, 창구 직원은 입금한 근로자들로부터 「H 사장에게 돈을 맡기면 고향 가족이 그 나라에서 바로 받는다」는 말을 들었다.\n3) 조합원 K는 미국 관할의 해외 결제 플랫폼이 제공하는 신용카드 소액 해외송금 서비스로 자기 카드를 결제해 본인 새봄신협 계좌로 돈을 보낸 뒤, 곧바로 현금으로 인출하는 일을 반복한다.\n4) 조합원 L은 가족 4명 명의로 계좌를 하나씩 새로 열면서 계좌마다 예금자보호한도에 맞춘 금액을 넣으려 하고, 입금 자금은 모두 L이 가져왔다.",
  "ask": "위험평가 보고서 초안의 서술로 가장 옳지 않은 것은?",
