  "ex": "정답 ④.\n① ○ 국가위험평가에서 위협(Threats)은 자금세탁·테러자금조달과 관련된 전제범죄 등이고, 취약성(Vulnerabilities)은 자금세탁의 기회를 제공하는 제도·기관·분야·규정·감독·특정 서비스·상품 등으로, AML/CFT 제도 등의 약한 부분이 취약요소가 된다(TPAC 핵심포인트 02 「국가위험평가 관련 주요개념」). 보이스피싱 등 금융사기는 한국의 주요 전제범죄 위험이다(같은 자료 「전제범죄 관련 위험」).\n② ○ 상호금융업 등은 은행의 대체 금융기관 역할을 하므로, 은행이 내부통제를 강화하면 자금세탁 위험이 상호금융업으로 전이될 가능성이 높아진다. 은행의 보이스피싱 통제가 강화되자 상호금융업권의 보이스피싱이 급증한 사례가 제시된다(TPAC 02 「저축은행, 상호금융업 관련」).\n③ ○ 신용카드 소액 해외송금 서비스를 이용해 필요한 만큼 카드를 결제한 뒤 자신의 은행계좌로 송금받아 현금을 쓰는 방법으로 카드깡이 이루어지며, 불법대출·외화유출·자금세탁이 발생할 수 있으나 해당 플랫폼이 미국 관할이라 규제에 한계가 있다(TPAC 02 「페이팔을 이용한 카드깡」).\n④ ✕ 2)는 국내 업자 계좌에 입금하면 국외 업자가 입금 사실을 확인하고 현지에서 수취인에게 지급하는 「환치기」(무등록 외국환 업무)의 전형이다. 실제로 국가 간 송금행위가 이루어지지 않더라도 환치기 수법은 국가 간 외국환업무로 간주된다(TPAC 02 「환치기란?」). 해외 송금 기록이 없다는 점은 오히려 환치기의 특징이므로, 외국환 관련 위험으로 기재하고 STR 여부를 검토해야 한다.\n⑤ ○ 예금자보호한도로 쪼개어 차명계좌를 개설하는 것은 상호금융업권의 ML/TF 취약점이다(TPAC 02 「상호금융업권의 ML/TF 취약점」). 고객이 실제 소유자인지 여부가 의심되면 신원·실제 소유자에 더해 금융거래의 목적과 거래자금의 원천 등을 확인해야 한다(특금법 제5조의2①2호).\n함정: 「해외로 나간 송금이 없으니 외국환 위험이 아니다」. 환치기는 돈이 국경을 넘지 않는 것처럼 보이게 하는 수법 자체가 핵심이다.",
